  { n = 111, slug = "defense-curl", name = "Defense Curl", strippedId = "DEFENSECURL", type = "NORMAL", damageClass = "status", pp = 40, priority = 0, target = "user", generation = 1, category = "net-good-stats", statChanges = { { stat = "defense", change = 1 } }, shortEffect = "Raises user’s Defense by one stage.", effect = "Raises user’s Defense by one stage. After this move is used, the power of Ice Ball and Rollout are doubled until the user leaves the field.", flags = { "metronome", "snatch" } },
