  { n = 113, slug = "light-screen", name = "Light Screen", strippedId = "LIGHTSCREEN", type = "PSYCHIC", damageClass = "status", pp = 30, priority = 0, target = "users-field", generation = 1, category = "field-effect", shortEffect = "Reduces damage from special attacks by 50% for five turns.", effect = "Erects a barrier around the user’s side of the field that reduces damage from special attacks by half for five turns. In double battles, the reduction is 1/3. Critical hits are not affected by the barrier. If the user is holding Light Clay, the barrier lasts for eight turns. Brick Break or Defog used by an opponent will destroy the barrier.", flags = { "metronome", "snatch" } },
