  { n = 116, slug = "focus-energy", name = "Focus Energy", strippedId = "FOCUSENERGY", type = "NORMAL", damageClass = "status", pp = 30, priority = 0, target = "user", generation = 1, category = "unique", shortEffect = "Increases the user’s chance to score a critical hit.", effect = "User’s critical hit rate is two levels higher until it leaves the field. If the user has already used Focus Energy since entering the field, this move will fail. This effect is passed on by Baton Pass.", flags = { "metronome", "snatch" } },
  { n = 117, slug = "bide", name = "Bide", strippedId = "BIDE", type = "NORMAL", damageClass = "physical", pp = 10, priority = 1, target = "user", generation = 1, category = "damage", shortEffect = "User waits for two turns, then hits back for twice the damage it took.", effect = "User waits for two turns. On the second turn, the user inflicts twice the damage it accumulated on the last Pokémon to hit it. Damage inflicted is typeless. This move cannot be selected by Sleep Talk.", flags = { "contact", "failinstruct", "metronome", "nosleeptalk", "protect" } },
  { n = 118, slug = "metronome", name = "Metronome", strippedId = "METRONOME", type = "NORMAL", damageClass = "status", pp = 10, priority = 0, target = "user", generation = 1, category = "unique", shortEffect = "Randomly selects and uses any move in the game.", effect = "Selects any move at random and uses it. Moves the user already knows are not eligible. Assist, meta, protection, and reflection moves are also not eligible; specifically, Assist, Chatter, Copycat, Counter, Covet, Destiny Bond, Detect, Endure, Feint, Focus Punch, Follow Me, Helping Hand, Me First, Metronome, Mimic, Mirror Coat, Mirror Move, Protect, Quick Guard, Sketch, Sleep Talk, Snatch, Struggle, Switcheroo, Thief, Trick, and Wide Guard will not be selected by this move. This move cannot be copied by Mimic or Mirror Move, nor selected by Assist, Metronome, or Sleep Talk.", flags = { "failcopycat", "failencore", "failinstruct", "failmimic", "noassist", "nosleeptalk" } },
  { n = 119, slug = "mirror-move", name = "Mirror Move", strippedId = "MIRRORMOVE", type = "FLYING", damageClass = "status", pp = 20, priority = 0, target = "selected-pokemon", generation = 1, category = "unique", shortEffect = "Uses the target’s last used move.", effect = "Uses the last move targeted at the user by a Pokémon still on the field. A move counts as targeting the user even if it hit multiple Pokémon, as long as the user was one of them; however, moves targeting the field itself do not count. If the user has not been targeted by an appropriate move since entering the field, or if no Pokémon that targeted the user remains on the field, this move will fail. Moves that failed, missed, had no effect, or were blocked are still copied. Assist moves, time-delayed moves, “meta” moves that operate on other moves/Pokémon/abilities, and some other special moves cannot be copied and are ignored; if the last move to hit the user was such a move, the previous move will be used instead. The full list of ignored moves is: Acid Armor, Acupressure, After You, Agility, Ally Switch, Amnesia, Aqua Ring, Aromatherapy, Aromatic Mist, Assist, Autotomize, Barrier, Baton Pass, Belch, Belly Drum, Bide, Bulk Up, Calm Mind, Camouflage, Celebrate, Charge, Coil, Conversion, Conversion 2, Copycat, Cosmic Power, Cotton Guard, Counter, Crafty Shield, Curse, Defend Order, Defense Curl, Destiny Bond, Detect, Doom Desire, Double Team, Dragon Dance, Electric Terrain, Endure, Final Gambit, Flower Shield, Focus Energy, Focus Punch, Follow Me, Future Sight, Geomancy, Grassy Terrain, Gravity, Growth, Grudge, Guard Split, Hail, Happy Hour, Harden, Haze, Heal Bell, Heal Order, Heal Pulse, Healing Wish, Helping Hand, Hold Hands, Hone Claws, Howl, Imprison, Ingrain, Ion Deluge, Iron Defense, King’s Shield, Light Screen, Lucky Chant, Lunar Dance, Magic Coat, Magnet Rise, Magnetic Flux, Mat Block, Me First, Meditate, Metronome, Milk Drink, Mimic, Minimize, Mirror Coat, Mirror Move, Mist, Misty Terrain, Moonlight, Morning Sun, Mud Sport, Nasty Plot, Nature Power, Perish Song, Power Split, Power Trick, Protect, Psych Up, Quick Guard, Quiver Dance, Rage Powder, Rain Dance, Recover, Recycle, Reflect, Reflect Type, Refresh, Rest, Rock Polish, Role Play, Roost, Rototiller, Safeguard, Sandstorm, Shadow Blast, Shadow Bolt, Shadow Half, Shadow Rush, Shadow Shed, Shadow Sky, Shadow Storm, Shadow Wave, Sharpen, Shell Smash, Shift Gear, Sketch, Slack Off, Sleep Talk, Snatch, Soft-Boiled, Spikes, Spiky Shield, Spit Up, Splash, Stealth Rock, Sticky Web, Stockpile, Struggle, Substitute, Sunny Day, Swallow, Swords Dance, Synthesis, Tail Glow, Tailwind, Teleport, Toxic Spikes, Transform, Water Sport, Wide Guard, Wish, Withdraw and Work Up. This move cannot be selected by Assist, Metronome, or Sleep Talk, nor forced by Encore.", flags = { "failcopycat", "failencore", "failinstruct", "failmimic", "noassist", "nosleeptalk" } },
