  { n = 154, slug = "fury-swipes", name = "Fury Swipes", strippedId = "FURYSWIPES", type = "NORMAL", damageClass = "physical", pp = 15, priority = 0, target = "selected-pokemon", generation = 1, power = 18, accuracy = 80, category = "damage", minHits = 2, maxHits = 5, shortEffect = "Hits 2-5 times in one turn.", effect = "Inflicts regular damage. Hits 2–5 times in one turn. Has a 3/8 chance each to hit 2 or 3 times, and a 1/8 chance each to hit 4 or 5 times. Averages to 3 hits per use.", flags = { "contact", "metronome", "mirror", "protect" } },
