  { n = 156, slug = "rest", name = "Rest", strippedId = "REST", type = "PSYCHIC", damageClass = "status", pp = 5, priority = 0, target = "user", generation = 1, category = "unique", shortEffect = "User sleeps for two turns, completely healing itself.", effect = "User falls to sleep and immediately regains all its HP. If the user has another major status effect, sleep will replace it. The user will always wake up after two turns, or one turn with Early Bird. This move fails if the Pokémon cannot fall asleep due to Uproar, Insomnia, or Vital Spirit. It also fails if the Pokémon is at full health or is already asleep.", flags = { "heal", "metronome", "snatch" } },
