  { n = 160, slug = "conversion", name = "Conversion", strippedId = "CONVERSION", type = "NORMAL", damageClass = "status", pp = 30, priority = 0, target = "user", generation = 1, category = "unique", shortEffect = "User’s type changes to the type of one of its moves at random.", effect = "User’s type changes to the type of one of its moves, selected at random. Hidden Power and Weather Ball are treated as Normal. Only moves with a different type are eligible, and Curse is never eligible. If the user has no suitable moves, this move will fail.", flags = { "metronome", "snatch" } },
  { n = 161, slug = "tri-attack", name = "Tri Attack", strippedId = "TRIATTACK", type = "NORMAL", damageClass = "special", pp = 10, priority = 0, target = "selected-pokemon", generation = 1, power = 80, accuracy = 100, effectChance = 20, ailment = "unknown", category = "damage-ailment", ailmentChance = 20, shortEffect = "Has a chance to burn, freeze, or paralyze the target.", effect = "Inflicts regular damage. Has a chance to burn, freeze, or paralyze the target. One of these effects is selected at random; they do not each have independent chances to occur.", flags = { "metronome", "mirror", "protect" } },
  { n = 162, slug = "super-fang", name = "Super Fang", strippedId = "SUPERFANG", type = "NORMAL", damageClass = "physical", pp = 10, priority = 0, target = "selected-pokemon", generation = 1, accuracy = 90, category = "damage", shortEffect = "Inflicts damage equal to half the target’s HP.", effect = "Inflicts typeless damage equal to half the target’s remaining HP.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 163, slug = "slash", name = "Slash", strippedId = "SLASH", type = "NORMAL", damageClass = "physical", pp = 20, priority = 0, target = "selected-pokemon", generation = 1, power = 70, accuracy = 100, category = "damage", critRate = 1, shortEffect = "Has an increased chance for a critical hit.", effect = "Inflicts regular damage. User’s critical hit rate is one level higher when using this move.", flags = { "contact", "metronome", "mirror", "protect", "slicing" } },
  { n = 164, slug = "substitute", name = "Substitute", strippedId = "SUBSTITUTE", type = "NORMAL", damageClass = "status", pp = 10, priority = 0, target = "user", generation = 1, category = "unique", shortEffect = "Transfers 1/4 of the user’s max HP into a doll, protecting the user from further damage or status changes until it breaks.", effect = "Transfers 1/4 the user’s max HP into a doll that absorbs damage and causes most negative move effects to fail. If the user leaves the field, the doll will vanish. If the user cannot pay the HP cost, this move will fail. The doll takes damage as normal, using the user’s stats and types, and will break when its HP reaches zero. Self-inflicted damage from confusion or recoil is not absorbed. Healing effects from opponents ignore the doll and heal the user as normal. Moves that work based on the user’s HP still do so; the doll’s HP does not influence any move. The doll will block major status effects, confusion, and flinching. The effects of Smelling Salts and Wake-Up Slap do not trigger against a doll, even if the Pokémon behind the doll has the appropriate major status effect. Multi-turn trapping moves like Wrap will hit the doll for their regular damage, but the multi-turn trapping and damage effects will not activate. Moves blocked or damage absorbed by the doll do not count as hitting the user or inflicting damage for any effects that respond to such, e.g., Avalanche, Counter, or a Rowap Berry. Magic Coat still works as normal, even against moves the doll would block. Opposing Pokémon that damage the doll with a leech move like Absorb are healed as normal. It will also block Acupressure, Block, the curse effect of Curse, Dream Eater, Embargo, Flatter, Gastro Acid, Grudge, Heal Block, Leech Seed, Lock-On, Mean Look, Mimic, Mind Reader, Nightmare, Pain Split, Psycho Shift, Spider Web, Sketch, Swagger, Switcheroo, Trick, Worry Seed, and Yawn. A Pokémon affected by Yawn before summoning the doll will still fall to sleep. The doll blocks Intimidate, but all other abilities act as though the doll did not exist. If the user has an ability that absorbs moves of a certain type for HP (such as Volt Absorb absorbing Thunder Wave), such moves will not be blocked. Life Orb and berries that cause confusion still work as normal, but their respective HP loss and confusion are absorbed/blocked by the doll. The user is still vulnerable to damage inflicted when entering or leaving the field, such as by Pursuit or Spikes; however, the doll will block the poison effect of Toxic Spikes. The doll is passed on by Baton Pass. It keeps its existing HP, but uses the replacement Pokémon’s stats and types for damage calculation. All other effects work as normal.", flags = { "metronome", "nonsky", "snatch" } },
  { n = 165, slug = "struggle", name = "Struggle", strippedId = "STRUGGLE", type = "NORMAL", damageClass = "physical", pp = 1, priority = 0, target = "random-opponent", generation = 1, power = 50, category = "damage", healing = -25, shortEffect = "User takes 1/4 its max HP in recoil.", effect = "Inflicts typeless regular damage. User takes 1/4 its max HP in recoil. Ignores accuracy and evasion modifiers. This move is used automatically when a Pokémon cannot use any other move legally, e.g., due to having no PP remaining or being under the effect of both Encore and Torment at the same time. This move’s recoil is not treated as recoil for the purposes of anything that affects recoil, such as the ability Rock Head. It also is not prevented by Magic Guard. This move cannot be copied by Mimic, Mirror Move, or Sketch, nor selected by Assist or Metronome, nor forced by Encore.", flags = { "contact", "failcopycat", "failencore", "failinstruct", "failmefirst", "failmimic", "noassist", "nosketch", "nosleeptalk", "protect" } },
  { n = 166, slug = "sketch", name = "Sketch", strippedId = "SKETCH", type = "NORMAL", damageClass = "status", pp = 1, priority = 0, target = "selected-pokemon", generation = 2, category = "unique", shortEffect = "Permanently becomes the target’s last used move.", effect = "Permanently replaces itself with the target’s last used move. If that move is Chatter or Struggle, this move will fail. This move cannot be copied by Mimic or Mirror Move, nor selected by Assist or Metronome, nor forced by Encore.", flags = { "allyanim", "bypasssub", "failcopycat", "failencore", "failinstruct", "failmimic", "noassist", "nosketch", "nosleeptalk" } },
  { n = 167, slug = "triple-kick", name = "Triple Kick", strippedId = "TRIPLEKICK", type = "FIGHTING", damageClass = "physical", pp = 10, priority = 0, target = "selected-pokemon", generation = 2, power = 10, accuracy = 90, category = "damage", minHits = 3, maxHits = 3, shortEffect = "Hits three times, increasing power by 100% with each successful hit.", effect = "Inflicts regular damage. Hits three times in the same turn. The second hit has double power, and the third hit has triple power. Each hit has a separate accuracy check, and this move stops if a hit misses. Skill Link does not apply.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 168, slug = "thief", name = "Thief", strippedId = "THIEF", type = "DARK", damageClass = "physical", pp = 25, priority = 0, target = "selected-pokemon", generation = 2, power = 60, accuracy = 100, category = "damage", shortEffect = "Takes the target’s item.", effect = "Inflicts regular damage. If the target is holding an item and the user is not, the user will permanently take the item. Damage is still inflicted if an item cannot be taken. Pokémon with Sticky Hold or Multitype are immune to the item theft effect. The target cannot recover its item with Recycle. This move cannot be selected by Assist or Metronome.", flags = { "contact", "failcopycat", "failmefirst", "mirror", "noassist", "protect" } },
  { n = 169, slug = "spider-web", name = "Spider Web", strippedId = "SPIDERWEB", type = "BUG", damageClass = "status", pp = 10, priority = 0, target = "selected-pokemon", generation = 2, category = "unique", shortEffect = "Prevents the target from leaving battle.", effect = "The target cannot switch out normally. Ignores accuracy and evasion modifiers. This effect ends when the user leaves the field. The target may still escape by using Baton Pass, U-turn, or a Shed Shell. Both the user and the target pass on this effect with Baton Pass.", flags = { "metronome", "mirror", "protect", "reflectable" } },
  { n = 170, slug = "mind-reader", name = "Mind Reader", strippedId = "MINDREADER", type = "NORMAL", damageClass = "status", pp = 5, priority = 0, target = "selected-pokemon", generation = 2, category = "unique", shortEffect = "Ensures that the user’s next move will hit the target.", effect = "If the user targets the same target again before the end of the next turn, the move it uses is guaranteed to hit. This move itself also ignores accuracy and evasion modifiers. One-hit KO moves are also guaranteed to hit, as long as the user is equal or higher level than the target. This effect also allows the user to hit Pokémon that are off the field due to moves such as Dig or Fly. If the target uses Detect or Protect while under the effect of this move, the user is not guaranteed to hit, but has a (100 - accuracy)% chance to break through the protection. This effect is passed on by Baton Pass.", flags = { "metronome", "mirror", "protect" } },
  { n = 171, slug = "nightmare", name = "Nightmare", strippedId = "NIGHTMARE", type = "GHOST", damageClass = "status", pp = 15, priority = 0, target = "selected-pokemon", generation = 2, accuracy = 100, ailment = "nightmare", category = "ailment", shortEffect = "Target loses 1/4 its max HP every turn as long as it’s asleep.", effect = "Only works on sleeping Pokémon. Gives the target a nightmare, damaging it for 1/4 its max HP every turn. If the target wakes up or leaves the field, this effect ends.", flags = { "metronome", "mirror", "protect" } },
  { n = 172, slug = "flame-wheel", name = "Flame Wheel", strippedId = "FLAMEWHEEL", type = "FIRE", damageClass = "physical", pp = 25, priority = 0, target = "selected-pokemon", generation = 2, power = 60, accuracy = 100, effectChance = 10, ailment = "burn", category = "damage-ailment", ailmentChance = 10, shortEffect = "Has a chance to burn the target. Lets frozen Pokémon thaw themselves.", effect = "Inflicts regular damage. Has a chance to burn the target. Frozen Pokémon may use this move, in which case they will thaw.", flags = { "contact", "defrost", "metronome", "mirror", "protect" } },
  { n = 173, slug = "snore", name = "Snore", strippedId = "SNORE", type = "NORMAL", damageClass = "special", pp = 15, priority = 0, target = "selected-pokemon", generation = 2, power = 50, accuracy = 100, effectChance = 30, category = "damage", flinchChance = 30, shortEffect = "Has a chance to make the target flinch. Only works if the user is sleeping.", effect = "Only usable if the user is sleeping. Inflicts regular damage. Has a chance to make the target flinch.", flags = { "bypasssub", "mirror", "protect", "sound" } },
  { n = 174, slug = "curse", name = "Curse", strippedId = "CURSE", type = "GHOST", damageClass = "status", pp = 10, priority = 0, target = "specific-move", generation = 2, category = "unique", shortEffect = "Ghosts pay half their max HP to hurt the target every turn. Others decrease Speed but raise Attack and Defense.", effect = "If the user is a Ghost: user pays half its max HP to place a curse on the target, damaging it for 1/4 its max HP every turn. Otherwise: Lowers the user’s Speed by one stage, and raises its Attack and Defense by one stage each. The curse effect is passed on by Baton Pass. This move cannot be copied by Mirror Move.", flags = { "bypasssub", "metronome" } },
  { n = 175, slug = "flail", name = "Flail", strippedId = "FLAIL", type = "NORMAL", damageClass = "physical", pp = 15, priority = 0, target = "selected-pokemon", generation = 2, accuracy = 100, category = "damage", shortEffect = "Inflicts more damage when the user has less HP remaining, with a maximum of 200 power.", effect = "Inflicts regular damage. Power varies inversely with the user’s proportional remaining HP. 64 * current HP / max HP | Power -----------------------: | ----: 0– 1 | 200 2– 5 | 150 6–12 | 100 13–21 | 80 22–42 | 40 43–64 | 20", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 176, slug = "conversion-2", name = "Conversion 2", strippedId = "CONVERSION2", type = "NORMAL", damageClass = "status", pp = 30, priority = 0, target = "selected-pokemon", generation = 2, category = "unique", shortEffect = "Changes the user’s type to a random type either resistant or immune to the last move used against it.", effect = "Changes the user’s type to a type either resistant or immune to the last damaging move that hit it. The new type is selected at random and cannot be a type the user already is. If there is no eligible new type, this move will fail.", flags = { "bypasssub", "metronome" } },
