  { n = 178, slug = "cotton-spore", name = "Cotton Spore", strippedId = "COTTONSPORE", type = "GRASS", damageClass = "status", pp = 40, priority = 0, target = "all-opponents", generation = 2, accuracy = 100, category = "net-good-stats", statChanges = { { stat = "speed", change = -2 } }, shortEffect = "Lowers the target’s Speed by two stages.", flags = { "metronome", "mirror", "powder", "protect", "reflectable" } },
