  { n = 180, slug = "spite", name = "Spite", strippedId = "SPITE", type = "GHOST", damageClass = "status", pp = 10, priority = 0, target = "selected-pokemon", generation = 2, accuracy = 100, category = "unique", shortEffect = "Lowers the PP of the target’s last used move by 4.", effect = "Lowers the PP of the target’s last used move by 4. If the target hasn’t used a move since entering the field, if it tried to use a move this turn and failed, or if its last used move has 0 PP remaining, this move will fail.", flags = { "bypasssub", "metronome", "mirror", "protect", "reflectable" } },
  { n = 181, slug = "powder-snow", name = "Powder Snow", strippedId = "POWDERSNOW", type = "ICE", damageClass = "special", pp = 25, priority = 0, target = "all-opponents", generation = 2, power = 40, accuracy = 100, effectChance = 10, ailment = "freeze", category = "damage-ailment", ailmentChance = 10, shortEffect = "Has a chance to freeze the target.", effect = "Inflicts regular damage. Has a chance to freeze the target.", flags = { "metronome", "mirror", "protect" } },
  { n = 182, slug = "protect", name = "Protect", strippedId = "PROTECT", type = "NORMAL", damageClass = "status", pp = 10, priority = 4, target = "user", generation = 2, ailment = "protect", category = "unique", shortEffect = "Prevents any moves from hitting the user this turn.", effect = "No moves will hit the user for the remainder of this turn. If the user is last to act this turn, this move will fail. If the user successfully used Detect, Endure, Protect, Quick Guard, or Wide Guard on the last turn, this move has a 50% chance to fail. Lock-On, Mind Reader, and No Guard provide a (100 – accuracy)% chance for moves to break through this move. This does not apply to one-hit KO moves (Fissure, Guillotine, Horn Drill, and Sheer Cold); those are always blocked by this move. Thunder during Rain Dance and Blizzard during Hail have a 30% chance to break through this move. The following effects are not prevented by this move: * Acupressure from an ally * Curse’s curse effect * Delayed damage from Doom Desire and Future Sight; however, these moves will be prevented if they are used this turn * Feint, which will also end this move’s protection after it hits * Imprison * Perish Song * Shadow Force * Moves that merely copy the user, such as Transform or Psych Up This move cannot be selected by Assist or Metronome.", flags = { "failcopycat", "noassist" } },
