  { n = 190, slug = "octazooka", name = "Octazooka", strippedId = "OCTAZOOKA", type = "WATER", damageClass = "special", pp = 10, priority = 0, target = "selected-pokemon", generation = 2, power = 65, accuracy = 85, effectChance = 50, category = "damage-lower", statChance = 50, statChanges = { { stat = "accuracy", change = -1 } }, shortEffect = "Has a chance to lower the target’s accuracy by one stage.", effect = "Inflicts regular damage. Has a chance to lower the target’s accuracy by one stage.", flags = { "bullet", "metronome", "mirror", "protect" } },
  { n = 191, slug = "spikes", name = "Spikes", strippedId = "SPIKES", type = "GROUND", damageClass = "status", pp = 20, priority = 0, target = "opponents-field", generation = 2, category = "field-effect", shortEffect = "Scatters Spikes, hurting opposing Pokémon that switch in.", effect = "Scatters spikes around the opposing field, which damage opposing Pokémon that enter the field for 1/8 of their max HP. Pokémon immune to Ground moves are immune to this damage, except during Gravity. Up to three layers of spikes may be laid down, adding 1/16 to the damage done: two layers of spikes damage for 3/16 max HP, and three layers damage for 1/4 max HP. Wonder Guard does not block damage from this effect. Rapid Spin removes this effect from its user’s side of the field. Defog removes this effect from its target’s side of the field.", flags = { "metronome", "mustpressure", "nonsky", "reflectable" } },
  { n = 192, slug = "zap-cannon", name = "Zap Cannon", strippedId = "ZAPCANNON", type = "ELECTRIC", damageClass = "special", pp = 5, priority = 0, target = "selected-pokemon", generation = 2, power = 120, accuracy = 50, effectChance = 100, ailment = "paralysis", category = "damage-ailment", ailmentChance = 100, shortEffect = "Has a chance to paralyze the target.", effect = "Inflicts regular damage. Has a chance to paralyze the target.", flags = { "bullet", "metronome", "mirror", "protect" } },
  { n = 193, slug = "foresight", name = "Foresight", strippedId = "FORESIGHT", type = "NORMAL", damageClass = "status", pp = 40, priority = 0, target = "selected-pokemon", generation = 2, ailment = "no-type-immunity", category = "ailment", shortEffect = "Forces the target to have no Evade, and allows it to be hit by Normal and Fighting moves even if it’s a Ghost.", effect = "Resets the target’s evasion to normal and prevents any further boosting until the target leaves the field. A Ghost under this effect takes normal damage from Normal and Fighting moves. This move itself ignores accuracy and evasion modifiers.", flags = { "bypasssub", "metronome", "mirror", "protect", "reflectable" } },
  { n = 194, slug = "destiny-bond", name = "Destiny Bond", strippedId = "DESTINYBOND", type = "GHOST", damageClass = "status", pp = 5, priority = 0, target = "user", generation = 2, category = "unique", shortEffect = "If the user faints this turn, the target automatically will, too.", effect = "If the user faints before its next move, the Pokémon that fainted it will automatically faint. End-of-turn damage is ignored. This move cannot be selected by Assist or Metronome.", flags = { "bypasssub", "failcopycat", "noassist" } },
  { n = 195, slug = "perish-song", name = "Perish Song", strippedId = "PERISHSONG", type = "NORMAL", damageClass = "status", pp = 5, priority = 0, target = "all-pokemon", generation = 2, ailment = "perish-song", category = "ailment", minTurns = 4, maxTurns = 4, shortEffect = "User and target both faint after three turns.", effect = "Every Pokémon is given a counter that starts at 3 and decreases by 1 at the end of every turn, including this one. When a Pokémon’s counter reaches zero, that Pokémon faints. A Pokémon that leaves the field will lose its counter; its replacement does not inherit the effect, and other Pokémon’s counters remain. This effect is passed on by Baton Pass. This move cannot be copied by Mirror Move.", flags = { "bypasssub", "distance", "metronome", "sound" } },
  { n = 196, slug = "icy-wind", name = "Icy Wind", strippedId = "ICYWIND", type = "ICE", damageClass = "special", pp = 15, priority = 0, target = "all-opponents", generation = 2, power = 55, accuracy = 95, effectChance = 100, category = "damage-lower", statChance = 100, statChanges = { { stat = "speed", change = -1 } }, shortEffect = "Has a chance to lower the target’s Speed by one stage.", effect = "Inflicts regular damage. Has a chance to lower the target’s Speed by one stage.", flags = { "metronome", "mirror", "protect", "wind" } },
  { n = 197, slug = "detect", name = "Detect", strippedId = "DETECT", type = "FIGHTING", damageClass = "status", pp = 5, priority = 4, target = "user", generation = 2, ailment = "protect", category = "unique", shortEffect = "Prevents any moves from hitting the user this turn.", effect = "No moves will hit the user for the remainder of this turn. If the user is last to act this turn, this move will fail. If the user successfully used Detect, Endure, Protect, Quick Guard, or Wide Guard on the last turn, this move has a 50% chance to fail. Lock-On, Mind Reader, and No Guard provide a (100 – accuracy)% chance for moves to break through this move. This does not apply to one-hit KO moves (Fissure, Guillotine, Horn Drill, and Sheer Cold); those are always blocked by this move. Thunder during Rain Dance and Blizzard during Hail have a 30% chance to break through this move. The following effects are not prevented by this move: * Acupressure from an ally * Curse’s curse effect * Delayed damage from Doom Desire and Future Sight; however, these moves will be prevented if they are used this turn * Feint, which will also end this move’s protection after it hits * Imprison * Perish Song * Shadow Force * Moves that merely copy the user, such as Transform or Psych Up This move cannot be selected by Assist or Metronome.", flags = { "failcopycat", "noassist" } },
  { n = 198, slug = "bone-rush", name = "Bone Rush", strippedId = "BONERUSH", type = "GROUND", damageClass = "physical", pp = 10, priority = 0, target = "selected-pokemon", generation = 2, power = 25, accuracy = 90, category = "damage", minHits = 2, maxHits = 5, shortEffect = "Hits 2-5 times in one turn.", effect = "Inflicts regular damage. Hits 2–5 times in one turn. Has a 3/8 chance each to hit 2 or 3 times, and a 1/8 chance each to hit 4 or 5 times. Averages to 3 hits per use.", flags = { "metronome", "mirror", "protect" } },
  { n = 199, slug = "lock-on", name = "Lock-On", strippedId = "LOCKON", type = "NORMAL", damageClass = "status", pp = 5, priority = 0, target = "selected-pokemon", generation = 2, category = "unique", shortEffect = "Ensures that the user’s next move will hit the target.", effect = "If the user targets the same target again before the end of the next turn, the move it uses is guaranteed to hit. This move itself also ignores accuracy and evasion modifiers. One-hit KO moves are also guaranteed to hit, as long as the user is equal or higher level than the target. This effect also allows the user to hit Pokémon that are off the field due to moves such as Dig or Fly. If the target uses Detect or Protect while under the effect of this move, the user is not guaranteed to hit, but has a (100 - accuracy)% chance to break through the protection. This effect is passed on by Baton Pass.", flags = { "metronome", "mirror", "protect" } },
  { n = 200, slug = "outrage", name = "Outrage", strippedId = "OUTRAGE", type = "DRAGON", damageClass = "physical", pp = 10, priority = 0, target = "random-opponent", generation = 2, power = 120, accuracy = 100, category = "damage", shortEffect = "Hits every turn for 2-3 turns, then confuses the user.", effect = "Inflicts regular damage. User is forced to attack with this move for 2–3 turns,selected at random. After the last hit, the user becomes confused. Safeguard does not protect against the confusion from this move.", flags = { "contact", "failinstruct", "metronome", "mirror", "protect" } },
  { n = 201, slug = "sandstorm", name = "Sandstorm", strippedId = "SANDSTORM", type = "ROCK", damageClass = "status", pp = 10, priority = 0, target = "entire-field", generation = 2, category = "whole-field-effect", shortEffect = "Changes the weather to a sandstorm for five turns.", effect = "Changes the weather to a sandstorm for five turns. Pokémon that are not Ground, Rock, or Steel take 1/16 their max HP at the end of every turn. Every Rock Pokémon’s original Special Defense is raised by 50% for the duration of this effect. Solar Beam’s power is halved. Moonlight, Morning Sun, and Synthesis only heal 1/4 the user’s max HP.", flags = { "metronome", "wind" } },
  { n = 202, slug = "giga-drain", name = "Giga Drain", strippedId = "GIGADRAIN", type = "GRASS", damageClass = "special", pp = 10, priority = 0, target = "selected-pokemon", generation = 2, power = 75, accuracy = 100, category = "damage-heal", drain = 50, shortEffect = "Drains half the damage inflicted to heal the user.", effect = "Inflicts regular damage. Drains half the damage inflicted to heal the user.", flags = { "heal", "metronome", "mirror", "protect" } },
  { n = 203, slug = "endure", name = "Endure", strippedId = "ENDURE", type = "NORMAL", damageClass = "status", pp = 10, priority = 4, target = "user", generation = 2, category = "unique", shortEffect = "Prevents the user’s HP from lowering below 1 this turn.", effect = "The user’s HP cannot be lowered below 1 by any means for the remainder of this turn. If the user successfully used Detect, Endure, Protect, Quick Guard, or Wide Guard on the last turn, this move has a 50% chance to fail. This move cannot be selected by Assist or Metronome.", flags = { "failcopycat", "noassist" } },
  { n = 204, slug = "charm", name = "Charm", strippedId = "CHARM", type = "FAIRY", damageClass = "status", pp = 20, priority = 0, target = "selected-pokemon", generation = 2, accuracy = 100, category = "net-good-stats", statChanges = { { stat = "attack", change = -2 } }, shortEffect = "Lowers the target’s Attack by two stages.", flags = { "allyanim", "metronome", "mirror", "protect", "reflectable" } },
  { n = 205, slug = "rollout", name = "Rollout", strippedId = "ROLLOUT", type = "ROCK", damageClass = "physical", pp = 20, priority = 0, target = "selected-pokemon", generation = 2, power = 30, accuracy = 90, category = "damage", shortEffect = "Power doubles every turn this move is used in succession after the first, resetting after five turns.", effect = "Inflicts regular damage. User is forced to use this move for five turns. Power doubles every time this move is used in succession to a maximum of 16x, and resets to normal after the lock-in ends. If this move misses or becomes unusable, the lock-in ends. If the user has used Defense Curl since entering the field, this move has double power.", flags = { "contact", "failinstruct", "metronome", "mirror", "noparentalbond", "protect" } },
  { n = 206, slug = "false-swipe", name = "False Swipe", strippedId = "FALSESWIPE", type = "NORMAL", damageClass = "physical", pp = 40, priority = 0, target = "selected-pokemon", generation = 2, power = 40, accuracy = 100, category = "damage", shortEffect = "Cannot lower the target’s HP below 1.", effect = "Inflicts regular damage. Will not reduce the target’s HP below 1.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 207, slug = "swagger", name = "Swagger", strippedId = "SWAGGER", type = "NORMAL", damageClass = "status", pp = 15, priority = 0, target = "selected-pokemon", generation = 2, accuracy = 85, ailment = "confusion", category = "swagger", minTurns = 2, maxTurns = 5, statChanges = { { stat = "attack", change = 2 } }, shortEffect = "Raises the target’s Attack by two stages and confuses the target.", effect = "Raises the target’s Attack by two stages, then confuses it. If the target’s Attack cannot be raised by two stages, the confusion is not applied.", flags = { "allyanim", "metronome", "mirror", "protect", "reflectable" } },
  { n = 208, slug = "milk-drink", name = "Milk Drink", strippedId = "MILKDRINK", type = "NORMAL", damageClass = "status", pp = 5, priority = 0, target = "user", generation = 2, category = "heal", healing = 50, shortEffect = "Heals the user by half its max HP.", effect = "Heals the user for half its max HP.", flags = { "heal", "metronome", "snatch" } },
  { n = 209, slug = "spark", name = "Spark", strippedId = "SPARK", type = "ELECTRIC", damageClass = "physical", pp = 20, priority = 0, target = "selected-pokemon", generation = 2, power = 65, accuracy = 100, effectChance = 30, ailment = "paralysis", category = "damage-ailment", ailmentChance = 30, shortEffect = "Has a chance to paralyze the target.", effect = "Inflicts regular damage. Has a chance to paralyze the target.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 210, slug = "fury-cutter", name = "Fury Cutter", strippedId = "FURYCUTTER", type = "BUG", damageClass = "physical", pp = 20, priority = 0, target = "selected-pokemon", generation = 2, power = 40, accuracy = 95, category = "damage", shortEffect = "Power doubles every turn this move is used in succession after the first, maxing out after five turns.", effect = "Inflicts regular damage. Power doubles after every time this move is used, whether consecutively or not, maxing out at 16x. If this move misses or the user leaves the field, power resets.", flags = { "contact", "metronome", "mirror", "protect", "slicing" } },
  { n = 211, slug = "steel-wing", name = "Steel Wing", strippedId = "STEELWING", type = "STEEL", damageClass = "physical", pp = 25, priority = 0, target = "selected-pokemon", generation = 2, power = 70, accuracy = 90, effectChance = 10, category = "damage-raise", statChance = 10, statChanges = { { stat = "defense", change = 1 } }, shortEffect = "Has a chance to raise the user’s Defense by one stage.", effect = "Inflicts regular damage. Has a chance to raise the user’s Defense one stage.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 212, slug = "mean-look", name = "Mean Look", strippedId = "MEANLOOK", type = "NORMAL", damageClass = "status", pp = 5, priority = 0, target = "selected-pokemon", generation = 2, category = "unique", shortEffect = "Prevents the target from leaving battle.", effect = "The target cannot switch out normally. Ignores accuracy and evasion modifiers. This effect ends when the user leaves the field. The target may still escape by using Baton Pass, U-turn, or a Shed Shell. Both the user and the target pass on this effect with Baton Pass.", flags = { "metronome", "mirror", "reflectable" } },
  { n = 213, slug = "attract", name = "Attract", strippedId = "ATTRACT", type = "NORMAL", damageClass = "status", pp = 15, priority = 0, target = "selected-pokemon", generation = 2, accuracy = 100, ailment = "infatuation", category = "ailment", shortEffect = "Target falls in love if it has the opposite gender, and has a 50% chance to refuse attacking the user.", effect = "Causes the target to fall in love with the user, giving it a 50% chance to do nothing each turn. If the user and target are the same gender, or either is genderless, this move will fail. If either Pokémon leaves the field, this effect ends.", flags = { "bypasssub", "metronome", "mirror", "protect", "reflectable" } },
  { n = 214, slug = "sleep-talk", name = "Sleep Talk", strippedId = "SLEEPTALK", type = "NORMAL", damageClass = "status", pp = 10, priority = 0, target = "user", generation = 2, category = "unique", shortEffect = "Randomly uses one of the user’s other three moves. Only works if the user is sleeping.", effect = "Only usable if the user is sleeping. Randomly selects and uses one of the user’s other three moves. Use of the selected move requires and costs 0 PP. This move will not select Assist, Bide, Bounce, Chatter, Copycat, Dig, Dive, Fly, Focus Punch, Me First, Metronome, Mirror Move, Shadow Force, Skull Bash, Sky Attack, Sky Drop, Sleep Talk, Solar Beam, Razor Wind, or Uproar. If the selected move requires a recharge turn—i.e., one of Blast Burn, Frenzy Plant, Giga Impact, Hydro Cannon, Hyper Beam, Roar of Time, or Rock Wrecker—and the user is still sleeping next turn, then it’s forced to use this move again and pay another PP for the recharge turn. This move cannot be copied by Mirror Move, nor selected by Assist, Metronome, or Sleep Talk.", flags = { "failcopycat", "failencore", "failinstruct", "failmimic", "noassist", "nosleeptalk" } },
  { n = 215, slug = "heal-bell", name = "Heal Bell", strippedId = "HEALBELL", type = "NORMAL", damageClass = "status", pp = 5, priority = 0, target = "user-and-allies", generation = 2, category = "unique", shortEffect = "Cures the entire party of major status effects.", effect = "Removes major status effects and confusion from every Pokémon in the user’s party.", flags = { "bypasssub", "distance", "metronome", "snatch", "sound" } },
  { n = 216, slug = "return", name = "Return", strippedId = "RETURN", type = "NORMAL", damageClass = "physical", pp = 20, priority = 0, target = "selected-pokemon", generation = 2, accuracy = 100, category = "damage", shortEffect = "Power increases with happiness, up to a maximum of 102.", effect = "Inflicts regular damage. Power increases with happiness, given by `happiness * 2 / 5`, to a maximum of 102. Power bottoms out at 1.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 217, slug = "present", name = "Present", strippedId = "PRESENT", type = "NORMAL", damageClass = "physical", pp = 15, priority = 0, target = "selected-pokemon", generation = 2, accuracy = 90, category = "damage", shortEffect = "Randomly inflicts damage with power from 40 to 120 or heals the target for 1/4 its max HP.", effect = "Randomly uses one of the following effects. Effect | Chance -------------------------------------------------- | -----: Inflicts regular damage with 40 power | 40% Inflicts regular damage with 80 power | 30% Inflicts regular damage with 120 power | 10% Heals the target for 1/4 its max HP | 20% On average, this move inflicts regular damage with 52 power and heals the target for 1/20 its max HP.", flags = { "metronome", "mirror", "protect" } },
  { n = 218, slug = "frustration", name = "Frustration", strippedId = "FRUSTRATION", type = "NORMAL", damageClass = "physical", pp = 20, priority = 0, target = "selected-pokemon", generation = 2, accuracy = 100, category = "damage", shortEffect = "Power increases as happiness decreases, up to a maximum of 102.", effect = "Inflicts regular damage. Power increases inversely with happiness, given by `(255 - happiness) * 2 / 5`, to a maximum of 102. Power bottoms out at 1.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 219, slug = "safeguard", name = "Safeguard", strippedId = "SAFEGUARD", type = "NORMAL", damageClass = "status", pp = 25, priority = 0, target = "users-field", generation = 2, category = "field-effect", shortEffect = "Protects the user’s field from major status ailments and confusion for five turns.", effect = "Protects Pokémon on the user’s side of the field from major status effects and confusion for five turns. Does not cancel existing ailments. This effect remains even if the user leaves the field. If Yawn is used while this move is in effect, it will immediately fail. Defog used by an opponent will end this effect. This effect does not prevent the confusion caused by Outrage, Petal Dance, or Thrash.", flags = { "metronome", "snatch" } },
  { n = 220, slug = "pain-split", name = "Pain Split", strippedId = "PAINSPLIT", type = "NORMAL", damageClass = "status", pp = 20, priority = 0, target = "selected-pokemon", generation = 2, category = "unique", shortEffect = "Sets the user’s and targets’s HP to the average of their current HP.", effect = "Changes the user’s and target’s remaining HP to the average of their current remaining HP. Ignores accuracy and evasion modifiers. This effect does not count as inflicting damage for other moves and effects that respond to damage taken. This effect fails against a Substitute.", flags = { "allyanim", "metronome", "mirror", "protect" } },
  { n = 221, slug = "sacred-fire", name = "Sacred Fire", strippedId = "SACREDFIRE", type = "FIRE", damageClass = "physical", pp = 5, priority = 0, target = "selected-pokemon", generation = 2, power = 100, accuracy = 95, effectChance = 50, ailment = "burn", category = "damage-ailment", ailmentChance = 50, shortEffect = "Has a chance to burn the target. Lets frozen Pokémon thaw themselves.", effect = "Inflicts regular damage. Has a chance to burn the target. Frozen Pokémon may use this move, in which case they will thaw.", flags = { "defrost", "metronome", "mirror", "protect" } },
  { n = 222, slug = "magnitude", name = "Magnitude", strippedId = "MAGNITUDE", type = "GROUND", damageClass = "physical", pp = 30, priority = 0, target = "all-other-pokemon", generation = 2, accuracy = 100, category = "damage", shortEffect = "Power varies randomly from 10 to 150.", effect = "Inflicts regular damage. Power is selected at random between 10 and 150, with an average of 71: Magnitude | Power | Chance --------: | ----: | -----: 4 | 10 | 5% 5 | 30 | 10% 6 | 50 | 20% 7 | 70 | 30% 8 | 90 | 20% 9 | 110 | 10% 10 | 150 | 5% This move has double power against Pokémon currently underground due to Dig.", flags = { "metronome", "mirror", "nonsky", "protect" } },
  { n = 223, slug = "dynamic-punch", name = "Dynamic Punch", strippedId = "DYNAMICPUNCH", type = "FIGHTING", damageClass = "physical", pp = 5, priority = 0, target = "selected-pokemon", generation = 2, power = 100, accuracy = 50, effectChance = 100, ailment = "confusion", category = "damage-ailment", ailmentChance = 100, minTurns = 2, maxTurns = 5, shortEffect = "Has a chance to confuse the target.", effect = "Inflicts regular damage. Has a chance to confuse the target.", flags = { "contact", "metronome", "mirror", "protect", "punch" } },
  { n = 224, slug = "megahorn", name = "Megahorn", strippedId = "MEGAHORN", type = "BUG", damageClass = "physical", pp = 10, priority = 0, target = "selected-pokemon", generation = 2, power = 120, accuracy = 85, category = "damage", shortEffect = "Inflicts regular damage with no additional effect.", effect = "Inflicts regular damage.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 225, slug = "dragon-breath", name = "Dragon Breath", strippedId = "DRAGONBREATH", type = "DRAGON", damageClass = "special", pp = 20, priority = 0, target = "selected-pokemon", generation = 2, power = 60, accuracy = 100, effectChance = 30, ailment = "paralysis", category = "damage-ailment", ailmentChance = 30, shortEffect = "Has a chance to paralyze the target.", effect = "Inflicts regular damage. Has a chance to paralyze the target.", flags = { "metronome", "mirror", "protect" } },
  { n = 226, slug = "baton-pass", name = "Baton Pass", strippedId = "BATONPASS", type = "NORMAL", damageClass = "status", pp = 40, priority = 0, target = "user", generation = 2, category = "unique", shortEffect = "Allows the trainer to switch out the user and pass effects along to its replacement.", effect = "User switches out, and the trainer selects a replacement Pokémon from the party. Stat changes, confusion, and persistent move effects are passed along to the replacement Pokémon. The following move effects are passed: * Aqua Ring * both the user’s and target’s effect of Block, Mean Look, and Spider Web * the curse effect of Curse * Embargo * Focus Energy or an activated Lansat Berry * Gastro Acid * Ingrain * being sapped by Leech Seed * being targeted by Lock-On or Mind Reader * Magnet Rise * Perish Song’s counter * Power Trick * Substitute; the doll’s HP is unchanged The replacement Pokémon does not trigger effects that respond to Pokémon switching in.", flags = { "metronome" } },
  { n = 227, slug = "encore", name = "Encore", strippedId = "ENCORE", type = "NORMAL", damageClass = "status", pp = 5, priority = 0, target = "selected-pokemon", generation = 2, accuracy = 100, category = "unique", shortEffect = "Forces the target to repeat its last used move every turn for 2 to 6 turns.", effect = "The next 4–8 times (selected at random) the target attempts to move, it is forced to repeat its last used move. If the selected move allows the trainer to select a target, an opponent will be selected at random each turn. If the target is prevented from using the selected move by some other effect, Struggle will be used instead. This effect ends if the selected move runs out of PP. If the target hasn’t used a move since entering the field, if it tried to use a move this turn and failed, if it does not know the selected move, or if the selected move has 0 PP remaining, this move will fail. If the target’s last used move was Encore, Mimic, Mirror Move, Sketch, Struggle, or Transform, this move will fail.", flags = { "bypasssub", "failencore", "metronome", "mirror", "protect", "reflectable" } },
  { n = 228, slug = "pursuit", name = "Pursuit", strippedId = "PURSUIT", type = "DARK", damageClass = "physical", pp = 20, priority = 0, target = "selected-pokemon", generation = 2, power = 40, accuracy = 100, category = "damage", shortEffect = "Has double power against, and can hit, Pokémon attempting to switch out.", effect = "Inflicts regular damage. If the target attempts to switch out this turn before the user acts, this move hits the target before it leaves and has double power. This effect can still hit a Pokémon that switches out when it has a Substitute up or when an ally has used Follow Me.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 229, slug = "rapid-spin", name = "Rapid Spin", strippedId = "RAPIDSPIN", type = "NORMAL", damageClass = "physical", pp = 40, priority = 0, target = "selected-pokemon", generation = 2, power = 50, accuracy = 100, effectChance = 100, category = "damage-raise", statChance = 100, statChanges = { { stat = "speed", change = 1 } }, shortEffect = "Frees the user from binding moves, removes Leech Seed, and blows away Spikes.", effect = "Inflicts regular damage. Removes Leech Seed from the user, frees the user from Bind, Clamp, Fire Spin, Magma Storm, Sand Tomb, Whirlpool, and Wrap, and clears Spikes, Stealth Rock, and Toxic Spikes from the user’s side of the field. If this move misses or has no effect, its effect doesn’t activate.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 230, slug = "sweet-scent", name = "Sweet Scent", strippedId = "SWEETSCENT", type = "NORMAL", damageClass = "status", pp = 20, priority = 0, target = "all-opponents", generation = 2, accuracy = 100, category = "net-good-stats", statChanges = { { stat = "evasion", change = -2 } }, shortEffect = "Lowers the target’s evasion by one stage.", flags = { "metronome", "mirror", "protect", "reflectable" } },
  { n = 231, slug = "iron-tail", name = "Iron Tail", strippedId = "IRONTAIL", type = "STEEL", damageClass = "physical", pp = 15, priority = 0, target = "selected-pokemon", generation = 2, power = 100, accuracy = 75, effectChance = 30, category = "damage-lower", statChance = 30, statChanges = { { stat = "defense", change = -1 } }, shortEffect = "Has a chance to lower the target’s Defense by one stage.", effect = "Inflicts regular damage. Has a chance to lower the target’s Defense by one stage.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 232, slug = "metal-claw", name = "Metal Claw", strippedId = "METALCLAW", type = "STEEL", damageClass = "physical", pp = 35, priority = 0, target = "selected-pokemon", generation = 2, power = 50, accuracy = 95, effectChance = 10, category = "damage-raise", statChance = 10, statChanges = { { stat = "attack", change = 1 } }, shortEffect = "Has a chance to raise the user’s Attack by one stage.", effect = "Inflicts regular damage. Has a chance to raise the user’s Attack one stage.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 233, slug = "vital-throw", name = "Vital Throw", strippedId = "VITALTHROW", type = "FIGHTING", damageClass = "physical", pp = 10, priority = -1, target = "selected-pokemon", generation = 2, power = 70, category = "damage", shortEffect = "Never misses.", effect = "Inflicts regular damage. Ignores accuracy and evasion modifiers.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 234, slug = "morning-sun", name = "Morning Sun", strippedId = "MORNINGSUN", type = "NORMAL", damageClass = "status", pp = 5, priority = 0, target = "user", generation = 2, category = "heal", healing = 50, shortEffect = "Heals the user by half its max HP. Affected by weather.", effect = "Heals the user for half its max HP. During Sunny Day, the healing is increased to 2/3 max HP. During Hail, Rain Dance, or Sandstorm, the healing is decreased to 1/4 max HP.", flags = { "heal", "metronome", "snatch" } },
  { n = 235, slug = "synthesis", name = "Synthesis", strippedId = "SYNTHESIS", type = "GRASS", damageClass = "status", pp = 5, priority = 0, target = "user", generation = 2, category = "heal", healing = 50, shortEffect = "Heals the user by half its max HP. Affected by weather.", effect = "Heals the user for half its max HP. During Sunny Day, the healing is increased to 2/3 max HP. During Hail, Rain Dance, or Sandstorm, the healing is decreased to 1/4 max HP.", flags = { "heal", "metronome", "snatch" } },
  { n = 236, slug = "moonlight", name = "Moonlight", strippedId = "MOONLIGHT", type = "FAIRY", damageClass = "status", pp = 5, priority = 0, target = "user", generation = 2, category = "heal", healing = 50, shortEffect = "Heals the user by half its max HP. Affected by weather.", effect = "Heals the user for half its max HP. During Sunny Day, the healing is increased to 2/3 max HP. During Hail, Rain Dance, or Sandstorm, the healing is decreased to 1/4 max HP.", flags = { "heal", "metronome", "snatch" } },
  { n = 237, slug = "hidden-power", name = "Hidden Power", strippedId = "HIDDENPOWER", type = "NORMAL", damageClass = "special", pp = 15, priority = 0, target = "selected-pokemon", generation = 2, power = 60, accuracy = 100, category = "damage", shortEffect = "Power and type depend upon user’s IVs. Power can range from 30 to 70.", effect = "Inflicts regular damage. Power and type are determined by the user’s IVs. Power is given by `x * 40 / 63 + 30`. `x` is obtained by arranging bit 1 from the IV for each of Special Defense, Special Attack, Speed, Defense, Attack, and HP in that order. (Bit 1 is 1 if the IV is of the form `4n + 2` or `4n + 3`. `x` is then 64 * Special Defense IV bit 1, plus 32 * Special Attack IV bit 1, etc.) Power is always between 30 and 70, inclusive. Average power is 49.5. Type is given by `y * 15 / 63`, where `y` is similar to `x` above, except constructed from bit 0. (Bit 0 is 1 if the IV is odd.) The result is looked up in the following table. Value | Type ----: | -------- 0 | Fighting 1 | Flying 2 | Poison 3 | Ground 4 | Rock 5 | Bug 6 | Ghost 7 | Steel 8 | Fire 9 | Water 10 | Grass 11 | Electric 12 | Psychic 13 | Ice 14 | Dragon 15 | Dark This move thus cannot be Normal. Most other types have an equal 1/16 chance to be selected, given random IVs. However, due to the flooring used here, Bug, Fighting, and Grass appear 5/64 of the time, and Dark only 1/64 of the time.", flags = { "metronome", "mirror", "protect" } },
  { n = 238, slug = "cross-chop", name = "Cross Chop", strippedId = "CROSSCHOP", type = "FIGHTING", damageClass = "physical", pp = 5, priority = 0, target = "selected-pokemon", generation = 2, power = 100, accuracy = 80, category = "damage", critRate = 1, shortEffect = "Has an increased chance for a critical hit.", effect = "Inflicts regular damage. User’s critical hit rate is one level higher when using this move.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 239, slug = "twister", name = "Twister", strippedId = "TWISTER", type = "DRAGON", damageClass = "special", pp = 20, priority = 0, target = "all-opponents", generation = 2, power = 40, accuracy = 100, effectChance = 20, category = "damage", flinchChance = 20, shortEffect = "Has a chance to make the target flinch.", effect = "Inflicts regular damage. Has a chance to make each target flinch. If the target is under the effect of Bounce, Fly, or Sky Drop, this move will hit with double power.", flags = { "metronome", "mirror", "protect", "wind" } },
  { n = 240, slug = "rain-dance", name = "Rain Dance", strippedId = "RAINDANCE", type = "WATER", damageClass = "status", pp = 5, priority = 0, target = "entire-field", generation = 2, category = "whole-field-effect", shortEffect = "Changes the weather to rain for five turns.", effect = "Changes the weather to rain for five turns, during which Water moves inflict 50% extra damage, and Fire moves inflict half damage. If the user is holding Damp Rock, this effect lasts for eight turns. Thunder has 100% accuracy. If the target has used Detect or Protect, Thunder has a (100 - accuracy)% chance to break through the protection. Solar Beam has half power. Moonlight, Morning Sun, and Synthesis heal only 1/4 of the user’s max HP. Pokémon with Swift Swim have doubled original Speed. Pokémon with Forecast become Water. Pokémon with Dry Skin heal 1/8 max HP, Pokémon with Hydration are cured of major status effects, and Pokémon with Rain Dish heal 1/16 max HP at the end of each turn.", flags = { "metronome" } },
  { n = 241, slug = "sunny-day", name = "Sunny Day", strippedId = "SUNNYDAY", type = "FIRE", damageClass = "status", pp = 5, priority = 0, target = "entire-field", generation = 2, category = "whole-field-effect", shortEffect = "Changes the weather to sunny for five turns.", effect = "Changes the weather to sunshine for five turns, during which Fire moves inflict 50% extra damage, and Water moves inflict half damage. If the user is holding Heat Rock, this effect lasts for eight turns. Pokémon cannot become frozen. Thunder has 50% accuracy. Solar Beam skips its charge turn. Moonlight, Morning Sun, and Synthesis heal 2/3 of the user’s max HP. Pokémon with Chlorophyll have doubled original Speed. Pokémon with Forecast become Fire. Pokémon with Leaf Guard are not affected by major status effects. Pokémon with Flower Gift change form; every Pokémon on their side of the field have their original Attack and Special Attack increased by 50%. Pokémon with Dry Skin lose 1/8 max HP at the end of each turn. Pokémon with Solar Power have their original Special Attack raised by 50% but lose 1/8 their max HP at the end of each turn.", flags = { "metronome" } },
  { n = 242, slug = "crunch", name = "Crunch", strippedId = "CRUNCH", type = "DARK", damageClass = "physical", pp = 15, priority = 0, target = "selected-pokemon", generation = 2, power = 80, accuracy = 100, effectChance = 20, category = "damage-lower", statChance = 20, statChanges = { { stat = "defense", change = -1 } }, shortEffect = "Has a chance to lower the target’s Defense by one stage.", effect = "Inflicts regular damage. Has a chance to lower the target’s Defense by one stage.", flags = { "bite", "contact", "metronome", "mirror", "protect" } },
  { n = 243, slug = "mirror-coat", name = "Mirror Coat", strippedId = "MIRRORCOAT", type = "PSYCHIC", damageClass = "special", pp = 20, priority = -5, target = "specific-move", generation = 2, accuracy = 100, category = "damage", shortEffect = "Inflicts twice the damage the user received from the last special hit it took.", effect = "Targets the last opposing Pokémon to hit the user with a special move this turn. Inflicts twice the damage that move did to the user. If there is no eligible target, this move will fail. Type immunity applies, but other type effects are ignored. This move cannot be copied by Mirror Move, nor selected by Assist or Metronome.", flags = { "failmefirst", "noassist", "protect" } },
  { n = 244, slug = "psych-up", name = "Psych Up", strippedId = "PSYCHUP", type = "NORMAL", damageClass = "status", pp = 10, priority = 0, target = "selected-pokemon", generation = 2, category = "unique", shortEffect = "Discards the user’s stat changes and copies the target’s.", effect = "Discards the user’s stat changes and copies the target’s. This move cannot be copied by Mirror Move.", flags = { "allyanim", "bypasssub", "metronome" } },
  { n = 245, slug = "extreme-speed", name = "Extreme Speed", strippedId = "EXTREMESPEED", type = "NORMAL", damageClass = "physical", pp = 5, priority = 2, target = "selected-pokemon", generation = 2, power = 80, accuracy = 100, category = "damage", shortEffect = "Inflicts regular damage with no additional effect.", effect = "Inflicts regular damage.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 246, slug = "ancient-power", name = "Ancient Power", strippedId = "ANCIENTPOWER", type = "ROCK", damageClass = "special", pp = 5, priority = 0, target = "selected-pokemon", generation = 2, power = 60, accuracy = 100, effectChance = 10, category = "damage-raise", statChance = 10, statChanges = { { stat = "attack", change = 1 }, { stat = "defense", change = 1 }, { stat = "special-attack", change = 1 }, { stat = "special-defense", change = 1 }, { stat = "speed", change = 1 } }, shortEffect = "Has a chance to raise all of the user’s stats by one stage.", effect = "Inflicts regular damage. Has a chance to raise all of the user’s stats one stage.", flags = { "metronome", "mirror", "protect" } },
  { n = 247, slug = "shadow-ball", name = "Shadow Ball", strippedId = "SHADOWBALL", type = "GHOST", damageClass = "special", pp = 15, priority = 0, target = "selected-pokemon", generation = 2, power = 80, accuracy = 100, effectChance = 20, category = "damage-lower", statChance = 20, statChanges = { { stat = "special-defense", change = -1 } }, shortEffect = "Has a chance to lower the target’s Special Defense by one stage.", effect = "Inflicts regular damage. Has a chance to lower the target’s Special Defense by one stage.", flags = { "bullet", "metronome", "mirror", "protect" } },
  { n = 248, slug = "future-sight", name = "Future Sight", strippedId = "FUTURESIGHT", type = "PSYCHIC", damageClass = "special", pp = 10, priority = 0, target = "selected-pokemon", generation = 2, power = 120, accuracy = 100, category = "unique", shortEffect = "Hits the target two turns later.", effect = "Inflicts typeless regular damage at the end of the third turn, starting with this one. This move cannot score a critical hit. If the target switches out, its replacement will be hit instead. Damage is calculated at the time this move is used; stat changes and switching out during the delay won’t change the damage inflicted. No move with this effect can be used against the same target again until after the end of the third turn. This effect breaks through Wonder Guard. If the target is protected by Protect or Detect on the turn this move is used, this move will fail. However, the damage on the third turn will break through protection. The damage is applied at the end of the turn, so it ignores Endure and Focus Sash. This move cannot be copied by Mirror Move.", flags = { "allyanim", "futuremove", "metronome" } },
  { n = 249, slug = "rock-smash", name = "Rock Smash", strippedId = "ROCKSMASH", type = "FIGHTING", damageClass = "physical", pp = 15, priority = 0, target = "selected-pokemon", generation = 2, power = 40, accuracy = 100, effectChance = 50, category = "damage-lower", statChance = 50, statChanges = { { stat = "defense", change = -1 } }, shortEffect = "Has a chance to lower the target’s Defense by one stage.", effect = "Inflicts regular damage. Has a chance to lower the target’s Defense by one stage.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 250, slug = "whirlpool", name = "Whirlpool", strippedId = "WHIRLPOOL", type = "WATER", damageClass = "special", pp = 15, priority = 0, target = "selected-pokemon", generation = 2, power = 35, accuracy = 85, effectChance = 100, ailment = "trap", category = "damage-ailment", ailmentChance = 100, minTurns = 5, maxTurns = 6, shortEffect = "Prevents the target from leaving battle and inflicts 1/16 its max HP in damage for 2-5 turns.", effect = "Inflicts regular damage. For the next 2–5 turns, the target cannot leave the field and is damaged for 1/16 its max HP at the end of each turn. The user continues to use other moves during this time. If the user leaves the field, this effect ends. Has a 3/8 chance each to hit 2 or 3 times, and a 1/8 chance each to hit 4 or 5 times. Averages to 3 hits per use. If the target is in the first turn of Dive, this move will hit with double power.", flags = { "metronome", "mirror", "protect" } },
  { n = 251, slug = "beat-up", name = "Beat Up", strippedId = "BEATUP", type = "DARK", damageClass = "physical", pp = 10, priority = 0, target = "selected-pokemon", generation = 2, accuracy = 100, category = "damage", minHits = 6, maxHits = 6, shortEffect = "Hits once for every conscious Pokémon the trainer has.", effect = "Inflicts typeless regular damage. Every Pokémon in the user’s party, excepting those that have fainted or have a major status effect, attacks the target. Calculated stats are ignored; the base stats for the target and assorted attackers are used instead. The random factor in the damage formula is not used. Dark Pokémon still get STAB. This effect breaks through Wonder Guard.", flags = { "allyanim", "metronome", "mirror", "protect" } },
  { n = 252, slug = "fake-out", name = "Fake Out", strippedId = "FAKEOUT", type = "NORMAL", damageClass = "physical", pp = 10, priority = 3, target = "selected-pokemon", generation = 3, power = 40, accuracy = 100, effectChance = 100, category = "damage", flinchChance = 100, shortEffect = "Can only be used as the first move after the user enters battle. Causes the target to flinch.", effect = "Inflicts regular damage. Causes the target to flinch. Can only be used on the user’s first turn after entering the field.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 253, slug = "uproar", name = "Uproar", strippedId = "UPROAR", type = "NORMAL", damageClass = "special", pp = 10, priority = 0, target = "random-opponent", generation = 3, power = 90, accuracy = 100, category = "damage", minTurns = 3, maxTurns = 3, shortEffect = "Forced to use this move for several turns. Pokémon cannot fall asleep in that time.", effect = "Inflicts regular damage. User is forced to use this move for 2–5 turns, selected at random. All Pokémon on the field wake up, and none can fall to sleep until the lock-in ends. Pokémon cannot use Rest during this effect. This move cannot be selected by Sleep Talk.", flags = { "bypasssub", "failinstruct", "metronome", "mirror", "nosleeptalk", "protect", "sound" } },
  { n = 254, slug = "stockpile", name = "Stockpile", strippedId = "STOCKPILE", type = "NORMAL", damageClass = "status", pp = 20, priority = 0, target = "user", generation = 3, category = "unique", statChanges = { { stat = "defense", change = 1 }, { stat = "special-defense", change = 1 } }, shortEffect = "Stores energy up to three times for use with Spit Up and Swallow.", effect = "Raises the user’s Defense and Special Defense by one stage each. Stores energy for use with Spit Up and Swallow. Up to three levels of energy can be stored, and all are lost if the user leaves the field. Energy is still stored even if the stat boosts cannot be applied. If the user uses Baton Pass, the stat boosts are passed as normal, but the stored energy is not.", flags = { "metronome", "snatch" } },
  { n = 255, slug = "spit-up", name = "Spit Up", strippedId = "SPITUP", type = "NORMAL", damageClass = "special", pp = 10, priority = 0, target = "selected-pokemon", generation = 3, accuracy = 100, category = "damage", shortEffect = "Power is 100 times the amount of energy Stockpiled.", effect = "Inflicts regular damage. Power is equal to 100 times the amount of energy stored by Stockpile. Ignores the random factor in the damage formula. Stored energy is consumed, and the user’s Defense and Special Defense are reset to what they would be if Stockpile had not been used. If the user has no energy stored, this move will fail. This move cannot be copied by Mirror Move.", flags = { "metronome", "protect" } },
  { n = 256, slug = "swallow", name = "Swallow", strippedId = "SWALLOW", type = "NORMAL", damageClass = "status", pp = 10, priority = 0, target = "user", generation = 3, category = "heal", healing = 25, shortEffect = "Recovers 1/4 HP after one Stockpile, 1/2 HP after two Stockpiles, or full HP after three Stockpiles.", effect = "Heals the user depending on the amount of energy stored by Stockpile: 1/4 its max HP after one use, 1/2 its max HP after two uses, or fully after three uses. Stored energy is consumed, and the user’s Defense and Special Defense are reset to what they would be if Stockpile had not been used. If the user has no energy stored, this move will fail.", flags = { "heal", "metronome", "snatch" } },
  { n = 257, slug = "heat-wave", name = "Heat Wave", strippedId = "HEATWAVE", type = "FIRE", damageClass = "special", pp = 10, priority = 0, target = "all-opponents", generation = 3, power = 95, accuracy = 90, effectChance = 10, ailment = "burn", category = "damage-ailment", ailmentChance = 10, shortEffect = "Has a chance to burn the target.", effect = "Inflicts regular damage. Has a chance to burn the target.", flags = { "metronome", "mirror", "protect", "wind" } },
  { n = 258, slug = "hail", name = "Hail", strippedId = "HAIL", type = "ICE", damageClass = "status", pp = 10, priority = 0, target = "entire-field", generation = 3, category = "whole-field-effect", shortEffect = "Changes the weather to a hailstorm for five turns.", effect = "Changes the weather to hail for five turns, during which non-Ice Pokémon are damaged for 1/16 their max HP at the end of every turn. If the user is holding Icy Rock, this effect lasts for eight turns. Blizzard has 100% accuracy. If the target has used Detect or Protect, Blizzard has a (100 - accuracy)% chance to break through the protection. Moonlight, Morning Sun, and Synthesis heal only 1/4 of the user’s max HP. Pokémon with Snow Cloak are exempt from this effect’s damage.", flags = { "metronome" } },
  { n = 259, slug = "torment", name = "Torment", strippedId = "TORMENT", type = "DARK", damageClass = "status", pp = 15, priority = 0, target = "selected-pokemon", generation = 3, accuracy = 100, ailment = "torment", category = "ailment", shortEffect = "Prevents the target from using the same move twice in a row.", effect = "Prevents the target from attempting to use the same move twice in a row. When the target leaves the field, this effect ends. If the target is forced to attempt a repeated move due to Choice Band, Choice Scarf, Choice Specs, Disable, Encore, Taunt, only having PP remaining for one move, or any other effect, the target will use Struggle instead. The target is then free to use the forced move next turn, as it didn’t use that move this turn.", flags = { "bypasssub", "metronome", "mirror", "protect", "reflectable" } },
  { n = 260, slug = "flatter", name = "Flatter", strippedId = "FLATTER", type = "DARK", damageClass = "status", pp = 15, priority = 0, target = "selected-pokemon", generation = 3, accuracy = 100, ailment = "confusion", category = "swagger", minTurns = 2, maxTurns = 5, statChanges = { { stat = "special-attack", change = 1 } }, shortEffect = "Raises the target’s Special Attack by one stage and confuses the target.", effect = "Raises the target’s Special Attack by one stage, then confuses it.", flags = { "allyanim", "metronome", "mirror", "protect", "reflectable" } },
  { n = 261, slug = "will-o-wisp", name = "Will-O-Wisp", strippedId = "WILLOWISP", type = "FIRE", damageClass = "status", pp = 15, priority = 0, target = "selected-pokemon", generation = 3, accuracy = 85, ailment = "burn", category = "ailment", shortEffect = "Burns the target.", flags = { "metronome", "mirror", "protect", "reflectable" } },
  { n = 262, slug = "memento", name = "Memento", strippedId = "MEMENTO", type = "DARK", damageClass = "status", pp = 10, priority = 0, target = "selected-pokemon", generation = 3, accuracy = 100, category = "unique", statChanges = { { stat = "attack", change = -2 }, { stat = "special-attack", change = -2 } }, shortEffect = "Lowers the target’s Attack and Special Attack by two stages. User faints.", flags = { "metronome", "mirror", "protect" } },
  { n = 263, slug = "facade", name = "Facade", strippedId = "FACADE", type = "NORMAL", damageClass = "physical", pp = 20, priority = 0, target = "selected-pokemon", generation = 3, power = 70, accuracy = 100, category = "damage", shortEffect = "Power doubles if user is burned, paralyzed, or poisoned.", effect = "Inflicts regular damage. If the user is burned, paralyzed, or poisoned, this move has double power.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 264, slug = "focus-punch", name = "Focus Punch", strippedId = "FOCUSPUNCH", type = "FIGHTING", damageClass = "physical", pp = 20, priority = -3, target = "selected-pokemon", generation = 3, power = 150, accuracy = 100, category = "damage", shortEffect = "If the user takes damage before attacking, the attack is canceled.", effect = "Inflicts regular damage. If the user takes damage this turn before hitting, this move will fail. This move cannot be copied by Mirror Move, nor selected by Assist, Metronome, or Sleep Talk.", flags = { "contact", "failcopycat", "failinstruct", "failmefirst", "noassist", "nosleeptalk", "protect", "punch" } },
  { n = 265, slug = "smelling-salts", name = "Smelling Salts", strippedId = "SMELLINGSALTS", type = "NORMAL", damageClass = "physical", pp = 10, priority = 0, target = "selected-pokemon", generation = 3, power = 70, accuracy = 100, category = "damage", shortEffect = "If the target is paralyzed, inflicts double damage and cures the paralysis.", effect = "Inflicts regular damage. If the target is paralyzed, this move has double power, and the target is cured of its paralysis.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 266, slug = "follow-me", name = "Follow Me", strippedId = "FOLLOWME", type = "NORMAL", damageClass = "status", pp = 20, priority = 2, target = "user", generation = 3, category = "unique", shortEffect = "Redirects the target’s single-target effects to the user for this turn.", effect = "Until the end of this turn, any moves that opposing Pokémon target solely at the user’s ally will instead target the user. If both Pokémon on the same side of the field use this move on the same turn, the Pokémon that uses it last will become the target. This effect takes priority over Lightning Rod and Storm Drain. If the user’s ally switches out, opposing Pokémon may still hit it with Pursuit. This move cannot be selected by Assist or Metronome.", flags = { "failcopycat", "noassist" } },
  { n = 267, slug = "nature-power", name = "Nature Power", strippedId = "NATUREPOWER", type = "NORMAL", damageClass = "status", pp = 20, priority = 0, target = "selected-pokemon", generation = 3, category = "unique", shortEffect = "Uses a move which depends upon the terrain.", effect = "Uses another move chosen according to the terrain. Terrain | Selected move ------------------------- | ------------------ Building | Tri Attack Cave | Rock Slide Deep water | Hydro Pump Desert | Earthquake Grass | Seed Bomb Mountain | Rock Slide Road | Earthquake Shallow water | Hydro Pump Snow | Blizzard Tall grass | Seed Bomb Electric Terrain | Thunderbolt Grassy Terrain | Energy Ball Misty Terrain | Moonblast In Pokémon Battle Revolution: Terrain | Selected move -------------- | ------------------ Courtyard | Tri Attack Crystal | Rock Slide Gateway | Hydro Pump Magma | Rock Slide Main Street | Tri Attack Neon | Tri Attack Stargazer | Rock Slide Sunny Park | Seed Bomb Sunset | Earthquake Waterfall | Seed Bomb This move cannot be copied by Mirror Move.", flags = { "failcopycat", "failencore", "failinstruct", "failmimic", "noassist", "nosleeptalk" } },
  { n = 268, slug = "charge", name = "Charge", strippedId = "CHARGE", type = "ELECTRIC", damageClass = "status", pp = 20, priority = 0, target = "user", generation = 3, category = "net-good-stats", statChanges = { { stat = "special-defense", change = 1 } }, shortEffect = "Raises the user’s Special Defense by one stage. User’s Electric moves have doubled power next turn.", effect = "Raises the user’s Special Defense by one stage. If the user uses an Electric move next turn, its power will be doubled.", flags = { "metronome", "snatch" } },
  { n = 269, slug = "taunt", name = "Taunt", strippedId = "TAUNT", type = "DARK", damageClass = "status", pp = 20, priority = 0, target = "selected-pokemon", generation = 3, accuracy = 100, category = "unique", shortEffect = "For the next few turns, the target can only use damaging moves.", effect = "Target is forced to only use damaging moves for the next 3–5 turns, selected at random. Moves that select other moves not known in advance do not count as damaging. Assist, Copycat, Me First, Metronome, Mirror Move, and Sleep Talk do not directly inflict damage and thus may not be used. Bide, Counter, Endeavor, Metal Burst, and Mirror Coat are allowed.", flags = { "bypasssub", "metronome", "mirror", "protect", "reflectable" } },
  { n = 270, slug = "helping-hand", name = "Helping Hand", strippedId = "HELPINGHAND", type = "NORMAL", damageClass = "status", pp = 20, priority = 5, target = "ally", generation = 3, category = "unique", shortEffect = "Ally’s next move inflicts half more damage.", effect = "Boosts the power of the target’s moves by 50% until the end of this turn. This move cannot be copied by Mirror Move, nor selected by Assist or Metronome.", flags = { "bypasssub", "failcopycat", "noassist" } },
  { n = 271, slug = "trick", name = "Trick", strippedId = "TRICK", type = "PSYCHIC", damageClass = "status", pp = 10, priority = 0, target = "selected-pokemon", generation = 3, accuracy = 100, category = "unique", shortEffect = "User and target swap items.", effect = "User and target permanently swap held items. Works even if one of the Pokémon isn’t holding anything. If either Pokémon is holding mail, this move will fail. If either Pokémon has Multitype or Sticky Hold, this move will fail. If this move results in a Pokémon obtaining Choice Band, Choice Scarf, or Choice Specs, and that Pokémon was the latter of the pair to move this turn, then the move it used this turn becomes its chosen forced move. This applies even if both Pokémon had a choice item before this move was used. If the first of the two Pokémon gains a choice item, it may select whatever choice move it wishes next turn. Neither the user nor the target can recover its item with Recycle. This move cannot be selected by Assist or Metronome.", flags = { "allyanim", "failcopycat", "mirror", "noassist", "protect" } },
  { n = 272, slug = "role-play", name = "Role Play", strippedId = "ROLEPLAY", type = "PSYCHIC", damageClass = "status", pp = 10, priority = 0, target = "selected-pokemon", generation = 3, category = "unique", shortEffect = "Copies the target’s ability.", effect = "User’s ability is replaced with the target’s until the user leaves the field. Ignores accuracy and evasion modifiers. If the target has Flower Gift, Forecast, Illusion, Imposter, Multitype, Stance Change, Trace, Wonder Guard, or Zen Mode, this move will fail. This move cannot be copied by Mirror Move.", flags = { "allyanim", "bypasssub", "metronome" } },
  { n = 273, slug = "wish", name = "Wish", strippedId = "WISH", type = "NORMAL", damageClass = "status", pp = 10, priority = 0, target = "user", generation = 3, category = "unique", shortEffect = "User will recover half its max HP at the end of the next turn.", effect = "At the end of the next turn, user will be healed for half its max HP. If the user is switched out, its replacement will be healed instead for half of the user’s max HP. If the user faints or is forcefully switched by Roar or Whirlwind, this effect will not activate.", flags = { "heal", "metronome", "snatch" } },
  { n = 274, slug = "assist", name = "Assist", strippedId = "ASSIST", type = "NORMAL", damageClass = "status", pp = 20, priority = 0, target = "user", generation = 3, category = "unique", shortEffect = "Randomly selects and uses one of the trainer’s other Pokémon’s moves.", effect = "Uses a move from another Pokémon in the user’s party, both selected at random. Moves from fainted Pokémon can be used. If there are no eligible Pokémon or moves, this move will fail. This move will not select Assist, Chatter, Circle Throw, Copycat, Counter, Covet, Destiny Bond, Detect, Dig, Dive, Dragon Tail, Endure, Feint, Fly Focus Punch, Follow Me, Helping Hand, Me First, Metronome, Mimic, Mirror Coat, Mirror Move, Phantom Force Protect, Quick Guard, Roar Shadow Force, Sketch, Sleep Talk, Snatch, Struggle, Switcheroo, Thief, Trick, Whirlwind, or Wide Guard. This move cannot be copied by Mirror Move, nor selected by Metronome or Sleep Talk.", flags = { "failcopycat", "failencore", "failinstruct", "failmimic", "noassist", "nosleeptalk" } },
  { n = 275, slug = "ingrain", name = "Ingrain", strippedId = "INGRAIN", type = "GRASS", damageClass = "status", pp = 20, priority = 0, target = "user", generation = 3, ailment = "ingrain", category = "ailment", shortEffect = "Prevents the user from leaving battle. User regains 1/16 of its max HP every turn.", effect = "Prevents the user from switching out. User regains 1/16 of its max HP at the end of every turn. If the user was immune to Ground attacks, it will now take normal damage from them. Roar and Whirlwind will not affect the user. The user cannot use Magnet Rise. The user may still use U-turn to leave the field. This effect can be passed with Baton Pass.", flags = { "metronome", "nonsky", "snatch" } },
  { n = 276, slug = "superpower", name = "Superpower", strippedId = "SUPERPOWER", type = "FIGHTING", damageClass = "physical", pp = 5, priority = 0, target = "selected-pokemon", generation = 3, power = 120, accuracy = 100, effectChance = 100, category = "damage-raise", statChance = 100, statChanges = { { stat = "attack", change = -1 }, { stat = "defense", change = -1 } }, shortEffect = "Lowers the user’s Attack and Defense by one stage after inflicting damage.", effect = "Inflicts regular damage, then lowers the user’s Attack and Defense by one stage each.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 277, slug = "magic-coat", name = "Magic Coat", strippedId = "MAGICCOAT", type = "PSYCHIC", damageClass = "status", pp = 15, priority = 4, target = "user", generation = 3, category = "unique", shortEffect = "Reflects back the first effect move used on the user this turn.", effect = "The first non-damaging move targeting the user this turn that inflicts major status effects, stat changes, or trapping effects will be reflected at its user. Defog, Memento, and Teeter Dance are not reflected. Attract, Flatter, Gastro Acid, Leech Seed, Swagger, Worry Seed, and Yawn are reflected. This move cannot be copied by Mirror Move.", flags = { "metronome" } },
  { n = 278, slug = "recycle", name = "Recycle", strippedId = "RECYCLE", type = "NORMAL", damageClass = "status", pp = 10, priority = 0, target = "user", generation = 3, category = "unique", shortEffect = "User recovers the item it last used up.", effect = "User recovers the last item consumed by the user or a Pokémon in its position on the field. The item must be used again before it can be recovered by this move again. If the user is holding an item, this move fails. Items taken or given away by Covet, Knock Off, Switcheroo, Thief, or Trick may not be recovered.", flags = { "metronome", "snatch" } },
  { n = 279, slug = "revenge", name = "Revenge", strippedId = "REVENGE", type = "FIGHTING", damageClass = "physical", pp = 10, priority = -4, target = "selected-pokemon", generation = 3, power = 60, accuracy = 100, category = "damage", shortEffect = "Inflicts double damage if the user takes damage before attacking this turn.", effect = "Inflicts regular damage. If the target damaged the user this turn and was the last to do so, this move has double power. Pain Split does not count as damaging the user.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 280, slug = "brick-break", name = "Brick Break", strippedId = "BRICKBREAK", type = "FIGHTING", damageClass = "physical", pp = 15, priority = 0, target = "selected-pokemon", generation = 3, power = 75, accuracy = 100, category = "damage", shortEffect = "Destroys Reflect and Light Screen.", effect = "Destroys any Light Screen or Reflect on the target’s side of the field, then inflicts regular damage.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 281, slug = "yawn", name = "Yawn", strippedId = "YAWN", type = "NORMAL", damageClass = "status", pp = 10, priority = 0, target = "selected-pokemon", generation = 3, ailment = "yawn", category = "ailment", minTurns = 2, maxTurns = 2, shortEffect = "Target sleeps at the end of the next turn.", effect = "Puts the target to sleep at the end of the next turn. Ignores accuracy and evasion modifiers. If the target leaves the field, this effect is canceled. If the target has a status effect when this move is used, this move will fail. If the target is protected by Safeguard when this move is used, this move will fail. Insomnia and Vital Spirit prevent the sleep if the target has either at the end of the next turn, but will not cause this move to fail on use.", flags = { "metronome", "mirror", "protect", "reflectable" } },
  { n = 282, slug = "knock-off", name = "Knock Off", strippedId = "KNOCKOFF", type = "DARK", damageClass = "physical", pp = 20, priority = 0, target = "selected-pokemon", generation = 3, power = 65, accuracy = 100, category = "damage", shortEffect = "Target drops its held item.", effect = "Inflicts regular damage. Target loses its held item. Neither the user nor the target can recover its item with Recycle. If the target has Multitype or Sticky Hold, it will take damage but not lose its item.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 283, slug = "endeavor", name = "Endeavor", strippedId = "ENDEAVOR", type = "NORMAL", damageClass = "physical", pp = 5, priority = 0, target = "selected-pokemon", generation = 3, accuracy = 100, category = "damage", shortEffect = "Lowers the target’s HP to equal the user’s.", effect = "Inflicts exactly enough damage to lower the target’s HP to equal the user’s. If the target’s HP is not higher than the user’s, this move has no effect. Type immunity applies, but other type effects are ignored. This effect counts as damage for moves that respond to damage.", flags = { "contact", "metronome", "mirror", "noparentalbond", "protect" } },
  { n = 284, slug = "eruption", name = "Eruption", strippedId = "ERUPTION", type = "FIRE", damageClass = "special", pp = 5, priority = 0, target = "all-opponents", generation = 3, power = 150, accuracy = 100, category = "damage", shortEffect = "Inflicts more damage when the user has more HP remaining, with a maximum of 150 power.", effect = "Inflicts regular damage. Power increases with the user’s remaining HP and is given by `150 * HP / max HP`, to a maximum of 150 when the user has full HP.", flags = { "metronome", "mirror", "protect" } },
  { n = 285, slug = "skill-swap", name = "Skill Swap", strippedId = "SKILLSWAP", type = "PSYCHIC", damageClass = "status", pp = 10, priority = 0, target = "selected-pokemon", generation = 3, category = "unique", shortEffect = "User and target swap abilities.", effect = "User and target switch abilities. Ignores accuracy and evasion modifiers. If either Pokémon has Multitype or Wonder Guard, this move will fail.", flags = { "allyanim", "bypasssub", "metronome", "mirror", "protect" } },
  { n = 286, slug = "imprison", name = "Imprison", strippedId = "IMPRISON", type = "PSYCHIC", damageClass = "status", pp = 10, priority = 0, target = "user", generation = 3, category = "unique", shortEffect = "Prevents the target from using any moves that the user also knows.", effect = "Prevents any Pokémon on the opposing side of the field from using any move the user knows until the user leaves the field. This effect is live; if the user obtains new moves while on the field, these moves become restricted. If no opposing Pokémon knows any of the user’s moves when this move is used, this move will fail.", flags = { "bypasssub", "metronome", "mustpressure", "snatch" } },
