  { n = 289, slug = "snatch", name = "Snatch", strippedId = "SNATCH", type = "DARK", damageClass = "status", pp = 10, priority = 4, target = "user", generation = 3, category = "unique", shortEffect = "Steals the target’s move, if it’s self-targeted.", effect = "The next time a Pokémon uses a beneficial move on itself or itself and its ally this turn, the user of this move will steal the move and use it itself. Moves which may be stolen by this move are identified by the \"snatchable\" flag. If two Pokémon use this move on the same turn, the faster Pokémon will steal the first beneficial move, and the slower Pokémon will then steal it again—thus, only the slowest Pokémon using this move ultimately gains a stolen move’s effect. If the user steals Psych Up, it will target the Pokémon that used Psych Up. If the user was the original target of Psych Up, and the Pokémon that originally used it’s affected by Pressure, it will only lose 1 PP. This move cannot be copied by Mirror Move, nor selected by Assist or Metronome.", flags = { "bypasssub", "failcopycat", "mustpressure", "noassist" } },
  { n = 290, slug = "secret-power", name = "Secret Power", strippedId = "SECRETPOWER", type = "NORMAL", damageClass = "physical", pp = 20, priority = 0, target = "selected-pokemon", generation = 3, power = 70, accuracy = 100, effectChance = 30, category = "damage", ailmentChance = 30, shortEffect = "Has a chance to inflict a status effect which depends upon the terrain.", effect = "Inflicts regular damage. Has a chance to inflict an effect chosen according to the terrain. Terrain | Effect -------------- | ------------------------------------------------------------- Building | Paralyzes target Cave | Makes target flinch Deep water | Lowers target’s Attack by one stage Desert | Lowers target’s accuracy by one stage Grass | Puts target to sleep Mountain | Makes target flinch Road | Lowers target’s accuracy by one stage Shallow water | Lowers target’s Attack by one stage Snow | Freezes target Tall grass | Puts target to sleep In Pokémon Battle Revolution: Terrain | Effect -------------- | ------------------------------------------------------------- Courtyard | Paralyzes target Crystal | Makes target flinch Gateway | Lowers target’s Attack by one stage Magma | Makes target flinch Main Street | Paralyzes target Neon | Paralyzes target Stargazer | Makes target flinch Sunny Park | Puts target to sleep Sunset | Lowers target’s accuracy by one stage Waterfall | Puts target to sleep", flags = { "metronome", "mirror", "protect" } },
  { n = 291, slug = "dive", name = "Dive", strippedId = "DIVE", type = "WATER", damageClass = "physical", pp = 10, priority = 0, target = "selected-pokemon", generation = 3, power = 80, accuracy = 100, category = "damage", shortEffect = "User dives underwater, dodging all attacks, and hits next turn.", effect = "Inflicts regular damage. User dives underwater for one turn, becoming immune to attack, and hits on the second turn. During the immune turn, Surf, and Whirlpool still hit the user normally, and their power is doubled if appropriate. The user may be hit during its immune turn if under the effect of Lock-On, Mind Reader, or No Guard. This move cannot be selected by Sleep Talk.", flags = { "allyanim", "charge", "contact", "failinstruct", "metronome", "mirror", "noassist", "nonsky", "nosleeptalk", "protect" } },
  { n = 292, slug = "arm-thrust", name = "Arm Thrust", strippedId = "ARMTHRUST", type = "FIGHTING", damageClass = "physical", pp = 20, priority = 0, target = "selected-pokemon", generation = 3, power = 15, accuracy = 100, category = "damage", minHits = 2, maxHits = 5, shortEffect = "Hits 2-5 times in one turn.", effect = "Inflicts regular damage. Hits 2–5 times in one turn. Has a 3/8 chance each to hit 2 or 3 times, and a 1/8 chance each to hit 4 or 5 times. Averages to 3 hits per use.", flags = { "contact", "metronome", "mirror", "protect" } },
