  { n = 328, slug = "sand-tomb", name = "Sand Tomb", strippedId = "SANDTOMB", type = "GROUND", damageClass = "physical", pp = 15, priority = 0, target = "selected-pokemon", generation = 3, power = 35, accuracy = 85, effectChance = 100, ailment = "trap", category = "damage-ailment", ailmentChance = 100, minTurns = 5, maxTurns = 6, shortEffect = "Prevents the target from fleeing and inflicts damage for 2-5 turns.", effect = "Inflicts regular damage. For the next 2–5 turns, the target cannot leave the field and is damaged for 1/16 its max HP at the end of each turn. The user continues to use other moves during this time. If the user leaves the field, this effect ends. Has a 3/8 chance each to hit 2 or 3 times, and a 1/8 chance each to hit 4 or 5 times. Averages to 3 hits per use. Rapid Spin cancels this effect.", flags = { "metronome", "mirror", "protect" } },
  { n = 329, slug = "sheer-cold", name = "Sheer Cold", strippedId = "SHEERCOLD", type = "ICE", damageClass = "special", pp = 5, priority = 0, target = "selected-pokemon", generation = 3, accuracy = 30, category = "ohko", shortEffect = "Causes a one-hit KO.", effect = "Inflicts damage equal to the target’s max HP. Ignores accuracy and evasion modifiers. This move’s accuracy is 30% plus 1% for each level the user is higher than the target. If the user is a lower level than the target, this move will fail. Because this move inflicts a specific and finite amount of damage, Endure still prevents the target from fainting. The effects of Lock-On, Mind Reader, and No Guard still apply, as long as the user is equal or higher level than the target. However, they will not give this move a chance to break through Detect or Protect.", flags = { "metronome", "mirror", "protect" } },
