  { n = 353, slug = "doom-desire", name = "Doom Desire", strippedId = "DOOMDESIRE", type = "STEEL", damageClass = "special", pp = 5, priority = 0, target = "selected-pokemon", generation = 3, power = 140, accuracy = 100, category = "unique", shortEffect = "Hits the target two turns later.", effect = "Inflicts typeless regular damage at the end of the third turn, starting with this one. This move cannot score a critical hit. If the target switches out, its replacement will be hit instead. Damage is calculated at the time this move is used; stat changes and switching out during the delay won’t change the damage inflicted. No move with this effect can be used against the same target again until after the end of the third turn. This effect breaks through Wonder Guard. If the target is protected by Protect or Detect on the turn this move is used, this move will fail. However, the damage on the third turn will break through protection. The damage is applied at the end of the turn, so it ignores Endure and Focus Sash. This move cannot be copied by Mirror Move.", flags = { "futuremove", "metronome" } },
  { n = 354, slug = "psycho-boost", name = "Psycho Boost", strippedId = "PSYCHOBOOST", type = "PSYCHIC", damageClass = "special", pp = 5, priority = 0, target = "selected-pokemon", generation = 3, power = 140, accuracy = 90, effectChance = 100, category = "damage-raise", statChance = 100, statChanges = { { stat = "special-attack", change = -2 } }, shortEffect = "Lowers the user’s Special Attack by two stages after inflicting damage.", effect = "Inflicts regular damage, then lowers the user’s Special Attack by two stages.", flags = { "metronome", "mirror", "protect" } },
  { n = 355, slug = "roost", name = "Roost", strippedId = "ROOST", type = "FLYING", damageClass = "status", pp = 5, priority = 0, target = "user", generation = 4, category = "heal", healing = 50, shortEffect = "Heals the user by half its max HP.", effect = "Heals the user for half its max HP. If the user is Flying, its Flying type is ignored until the end of this turn.", flags = { "heal", "metronome", "snatch" } },
  { n = 356, slug = "gravity", name = "Gravity", strippedId = "GRAVITY", type = "PSYCHIC", damageClass = "status", pp = 5, priority = 0, target = "entire-field", generation = 4, category = "whole-field-effect", shortEffect = "Disables moves and immunities that involve flying or levitating for five turns.", effect = "For five turns (including this one), all immunities to Ground moves are disabled. For the duration of this effect, the evasion of every Pokémon on the field is lowered by two stages. Cancels the effects of Bounce, Fly, and Sky Drop. Specifically, Flying Pokémon and those with Levitate or that have used Magnet Rise are no longer immune to Ground attacks, Arena Trap, Spikes, or Toxic Spikes. Bounce, Fly, Sky Drop, High Jump Kick, Jump Kick, and Splash cannot be used while this move is in effect. *Bug*: If this move is used during a double or triple battle while Pokémon are under the effect of Sky Drop, Sky Drop’s effect is not correctly canceled on its target, and it remains high in the air indefinitely. As Sky Drop prevents the target from acting, the only way to subsequently remove it from the field is to faint it.", flags = { "metronome", "nonsky" } },
  { n = 357, slug = "miracle-eye", name = "Miracle Eye", strippedId = "MIRACLEEYE", type = "PSYCHIC", damageClass = "status", pp = 40, priority = 0, target = "selected-pokemon", generation = 4, ailment = "no-type-immunity", category = "ailment", shortEffect = "Forces the target to have no evasion, and allows it to be hit by Psychic moves even if it’s Dark.", effect = "Resets the target’s evasion to normal and prevents any further boosting until the target leaves the field. A Dark Pokémon under this effect takes normal damage from Psychic moves. This move itself ignores accuracy and evasion modifiers.", flags = { "bypasssub", "metronome", "mirror", "protect", "reflectable" } },
  { n = 358, slug = "wake-up-slap", name = "Wake-Up Slap", strippedId = "WAKEUPSLAP", type = "FIGHTING", damageClass = "physical", pp = 10, priority = 0, target = "selected-pokemon", generation = 4, power = 70, accuracy = 100, category = "damage", shortEffect = "If the target is asleep, has double power and wakes it up.", effect = "Inflicts regular damage. If the target is sleeping, this move has double power, and the target wakes up.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 359, slug = "hammer-arm", name = "Hammer Arm", strippedId = "HAMMERARM", type = "FIGHTING", damageClass = "physical", pp = 10, priority = 0, target = "selected-pokemon", generation = 4, power = 100, accuracy = 90, effectChance = 100, category = "damage-raise", statChance = 100, statChanges = { { stat = "speed", change = -1 } }, shortEffect = "Lowers user’s Speed by one stage.", effect = "Inflicts regular damage, then lowers the user’s Speed by one stage.", flags = { "contact", "metronome", "mirror", "protect", "punch" } },
  { n = 360, slug = "gyro-ball", name = "Gyro Ball", strippedId = "GYROBALL", type = "STEEL", damageClass = "physical", pp = 5, priority = 0, target = "selected-pokemon", generation = 4, accuracy = 100, category = "damage", shortEffect = "Power raises when the user has lower Speed, up to a maximum of 150.", effect = "Inflicts regular damage. Power increases with the target’s current Speed compared to the user, given by `1 + 25 * target Speed / user Speed`, capped at 150.", flags = { "bullet", "contact", "metronome", "mirror", "protect" } },
  { n = 361, slug = "healing-wish", name = "Healing Wish", strippedId = "HEALINGWISH", type = "PSYCHIC", damageClass = "status", pp = 10, priority = 0, target = "user", generation = 4, category = "unique", shortEffect = "User faints. Its replacement has its HP fully restored and any major status effect removed.", effect = "User faints. Its replacement’s HP is fully restored, and any major status effect is removed. If the replacement Pokémon is immediately fainted by a switch-in effect, the next replacement is healed by this move instead.", flags = { "heal", "metronome", "snatch" } },
  { n = 362, slug = "brine", name = "Brine", strippedId = "BRINE", type = "WATER", damageClass = "special", pp = 10, priority = 0, target = "selected-pokemon", generation = 4, power = 65, accuracy = 100, category = "damage", shortEffect = "Has double power against Pokémon that have less than half their max HP remaining.", effect = "Inflicts regular damage. If the target has less than half its max HP remaining, this move has double power.", flags = { "metronome", "mirror", "protect" } },
  { n = 363, slug = "natural-gift", name = "Natural Gift", strippedId = "NATURALGIFT", type = "NORMAL", damageClass = "physical", pp = 15, priority = 0, target = "selected-pokemon", generation = 4, accuracy = 100, category = "damage", shortEffect = "Power and type depend on the held berry.", effect = "Inflicts regular damage. Power and type are determined by the user’s held berry. The berry is consumed. If the user is not holding a berry, this move will fail.", flags = { "metronome", "mirror", "protect" } },
  { n = 364, slug = "feint", name = "Feint", strippedId = "FEINT", type = "NORMAL", damageClass = "physical", pp = 10, priority = 2, target = "selected-pokemon", generation = 4, power = 30, accuracy = 100, category = "damage", shortEffect = "Hits through Protect and Detect.", effect = "Inflicts regular damage. Removes the effects of Detect or Protect from the target before hitting. This move cannot be copied by Mirror Move, nor selected by Assist or Metronome.", flags = { "failcopycat", "mirror", "noassist" } },
  { n = 365, slug = "pluck", name = "Pluck", strippedId = "PLUCK", type = "FLYING", damageClass = "physical", pp = 20, priority = 0, target = "selected-pokemon", generation = 4, power = 60, accuracy = 100, category = "damage", shortEffect = "If target has a berry, inflicts double damage and uses the berry.", effect = "Inflicts regular damage. If the target is holding a berry, this move has double power, and the user takes the berry and uses it immediately. If the target is holding a Jaboca Berry or Rowap Berry, the berry is still removed, but has no effect. If this move is super effective and the target is holding a berry that can reduce this move’s damage, it will do so, and will not be stolen.", flags = { "contact", "distance", "metronome", "mirror", "protect" } },
  { n = 366, slug = "tailwind", name = "Tailwind", strippedId = "TAILWIND", type = "FLYING", damageClass = "status", pp = 15, priority = 0, target = "users-field", generation = 4, category = "field-effect", shortEffect = "For three turns, friendly Pokémon have doubled Speed.", effect = "For the next three turns, all Pokémon on the user’s side of the field have their original Speed doubled. This effect remains if the user leaves the field.", flags = { "metronome", "snatch", "wind" } },
  { n = 367, slug = "acupressure", name = "Acupressure", strippedId = "ACUPRESSURE", type = "NORMAL", damageClass = "status", pp = 30, priority = 0, target = "user-or-ally", generation = 4, category = "unique", shortEffect = "Raises one of a friendly Pokémon’s stats at random by two stages.", effect = "Raises one of the target’s stats by two stages. The raised stat is chosen at random from any stats that can be raised by two stages. If no stat is eligible, this move will fail. If the target has a Substitute, this move will have no effect, even if the user is the target. This move cannot be copied by Mirror Move.", flags = { "metronome" } },
  { n = 368, slug = "metal-burst", name = "Metal Burst", strippedId = "METALBURST", type = "STEEL", damageClass = "physical", pp = 10, priority = 0, target = "specific-move", generation = 4, accuracy = 100, category = "damage", shortEffect = "Strikes back at the last Pokémon to hit the user this turn with 1.5× the damage.", effect = "Targets the last opposing Pokémon to hit the user with a damaging move this turn. Inflicts 1.5× the damage that move did to the user. If there is no eligible target, this move will fail. Type immunity applies, but other type effects are ignored.", flags = { "failmefirst", "metronome", "mirror", "protect" } },
  { n = 369, slug = "u-turn", name = "U-turn", strippedId = "UTURN", type = "BUG", damageClass = "physical", pp = 20, priority = 0, target = "selected-pokemon", generation = 4, power = 70, accuracy = 100, category = "damage", shortEffect = "User must switch out after attacking.", effect = "Inflicts regular damage, then the user immediately switches out, and the trainer selects a replacement Pokémon from the party. If the target faints from this attack, the user’s trainer selects the new Pokémon to send out first. If the user is the last Pokémon in its party that can battle, it will not switch out. The user may be hit by Pursuit when it switches out, if it has been targeted and Pursuit has not yet been used. This move may be used even if the user is under the effect of Ingrain. Ingrain’s effect will end.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 370, slug = "close-combat", name = "Close Combat", strippedId = "CLOSECOMBAT", type = "FIGHTING", damageClass = "physical", pp = 5, priority = 0, target = "selected-pokemon", generation = 4, power = 120, accuracy = 100, effectChance = 100, category = "damage-raise", statChance = 100, statChanges = { { stat = "defense", change = -1 }, { stat = "special-defense", change = -1 } }, shortEffect = "Lowers the user’s Defense and Special Defense by one stage after inflicting damage.", effect = "Inflicts regular damage, then lowers the user’s Defense and Special Defense by one stage each.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 371, slug = "payback", name = "Payback", strippedId = "PAYBACK", type = "DARK", damageClass = "physical", pp = 10, priority = 0, target = "selected-pokemon", generation = 4, power = 50, accuracy = 100, category = "damage", shortEffect = "Power is doubled if the target has already moved this turn.", effect = "Inflicts regular damage. If the target uses a move or switches out this turn before this move is used, this move has double power.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 372, slug = "assurance", name = "Assurance", strippedId = "ASSURANCE", type = "DARK", damageClass = "physical", pp = 10, priority = 0, target = "selected-pokemon", generation = 4, power = 60, accuracy = 100, category = "damage", shortEffect = "Power is doubled if the target has already received damage this turn.", effect = "Inflicts regular damage. If the target takes damage this turn for any reason before this move is used, this move has double power.", flags = { "contact", "metronome", "mirror", "protect" } },
  { n = 373, slug = "embargo", name = "Embargo", strippedId = "EMBARGO", type = "DARK", damageClass = "status", pp = 15, priority = 0, target = "selected-pokemon", generation = 4, accuracy = 100, ailment = "embargo", category = "ailment", minTurns = 5, maxTurns = 5, shortEffect = "Target cannot use held items.", effect = "Target cannot use its held item for five turns. If the target leaves the field, this effect ends. If a Pokémon under this effect uses Bug Bite or Pluck on a Pokémon holding a berry, the berry is destroyed but not used. If a Pokémon under this effect uses Fling, it will fail. This effect is passed by Baton Pass.", flags = { "metronome", "mirror", "protect", "reflectable" } },
  { n = 374, slug = "fling", name = "Fling", strippedId = "FLING", type = "DARK", damageClass = "physical", pp = 10, priority = 0, target = "selected-pokemon", generation = 4, accuracy = 100, category = "damage", shortEffect = "Throws held item at the target; power depends on the item.", effect = "Inflicts regular damage. Power and type are determined by the user’s held item. The item is consumed. If the user is not holding an item, or its item has no set type and power, this move will fail. This move ignores Sticky Hold. If the user is under the effect of Embargo, this move will fail.", flags = { "allyanim", "metronome", "mirror", "noparentalbond", "protect" } },
  { n = 375, slug = "psycho-shift", name = "Psycho Shift", strippedId = "PSYCHOSHIFT", type = "PSYCHIC", damageClass = "status", pp = 10, priority = 0, target = "selected-pokemon", generation = 4, accuracy = 100, category = "unique", shortEffect = "Transfers the user’s major status effect to the target.", effect = "If the user has a major status effect and the target does not, the user’s status is transferred to the target.", flags = { "metronome", "mirror", "protect" } },
