  { n = 377, slug = "heal-block", name = "Heal Block", strippedId = "HEALBLOCK", type = "PSYCHIC", damageClass = "status", pp = 15, priority = 0, target = "all-opponents", generation = 4, accuracy = 100, ailment = "heal-block", category = "ailment", minTurns = 5, maxTurns = 5, shortEffect = "Prevents target from restoring its HP for five turns.", effect = "For the next five turns, the target may not use any moves that only restore HP, and move effects that heal the target are disabled. Moves that steal HP may still be used, but will only inflict damage and not heal the target.", flags = { "metronome", "mirror", "protect", "reflectable" } },
  { n = 378, slug = "wring-out", name = "Wring Out", strippedId = "WRINGOUT", type = "NORMAL", damageClass = "special", pp = 5, priority = 0, target = "selected-pokemon", generation = 4, accuracy = 100, category = "damage", shortEffect = "Power increases against targets with more HP remaining, up to a maximum of 121 power.", effect = "Inflicts regular damage. Power directly relates to the target’s relative remaining HP, given by `1 + 120 * current HP / max HP`, to a maximum of 121.", flags = { "contact", "metronome", "mirror", "protect" } },
