  { n = 390, slug = "toxic-spikes", name = "Toxic Spikes", strippedId = "TOXICSPIKES", type = "POISON", damageClass = "status", pp = 20, priority = 0, target = "opponents-field", generation = 4, category = "field-effect", shortEffect = "Scatters poisoned spikes, poisoning opposing Pokémon that switch in.", effect = "Scatters poisoned spikes around the opposing field, which poison opposing Pokémon that enter the field. A second layer of these spikes may be laid down, in which case Pokémon will be badly poisoned instead. Pokémon immune to either Ground moves or being poisoned are immune to this effect. Pokémon otherwise immune to Ground moves are affected during Gravity. If a Poison Pokémon not immune to Ground moves enters a field covered with poisoned spikes, the spikes are removed. Rapid Spin will remove this effect from its user’s side of the field. Defog will remove this effect from its target’s side of the field. This move does not trigger Synchronize, unless the Pokémon with Synchronize was forced to enter the field by another effect such as Roar. Pokémon entering the field due to Baton Pass are not affected by this effect.", flags = { "metronome", "mustpressure", "nonsky", "reflectable" } },
